pub fn point_from(v: &Value) -> AppResult<Option<Point>> {
    match v {
        Value::Null => Ok(None),
        Value::Object(o) => {
            let mut p = Point::default();
            for (k, val) in o {
                match k.as_str() {
                    "x" => p.x = prim_f64(val)?,
                    "y" => p.y = prim_f64(val)?,
                    _ => return unknown_prop("Point2D.Double", k),
                }
            }
            Ok(Some(p))
        }
        _ => json_err("cannot deserialize Point2D.Double"),
    }
}

pub fn point_json(p: &Option<Point>) -> Value {
    match p {
        None => Value::Null,
        Some(p) => obj(vec![("x", j(p.x)), ("y", j(p.y))]),
    }
}

