    pub wmts: bool,
    pub matrix_ids: Option<Vec<String>>,
}

impl TileGrid {
    /// The Jackson constructor sets the tile size to 256.
    pub fn new_default(wmts: bool) -> TileGrid {
        TileGrid {
            tile_size: Some(256),
            wmts,
            ..Default::default()
        }
    }

    pub fn apply(&mut self, key: &str, v: &Value) -> AppResult<()> {
        match key {
            "id" => self.id = opt_i32(v)?,
            "type" => self.type_ = opt_string(v)?,
            "tileGridOrigin" => self.origin = point_from(v)?,
            "tileGridExtent" => {
                self.extent = match v {
                    Value::Null => None,
                    _ => Some(Extent::from_value(v)?),
                }
            }
            "tileSize" => self.tile_size = opt_i32(v)?,
            "tileGridResolutions" => self.resolutions = opt_f64_list(v)?,
            "matrixIds" if self.wmts => self.matrix_ids = opt_string_list(v)?,
            _ => return unknown_prop("TileGrid", key),
        }
        Ok(())
    }

    pub fn to_json(&self) -> Value {
        let mut m = obj_map(vec![
            ("id", j(self.id)),
            ("type", j(&self.type_)),
            ("tileGridOrigin", point_json(&self.origin)),
            (
                "tileGridExtent",
                self.extent.as_ref().map(|e| e.to_json()).unwrap_or(Value::Null),
            ),
            ("tileSize", j(self.tile_size)),
            ("tileGridResolutions", f64_list_json(&self.resolutions)),
        ]);
        if self.wmts {
            m.insert(
                "matrixIds".into(),
                match &self.matrix_ids {
                    None => Value::Null,
                    Some(ids) => Value::Array(ids.iter().map(|s| j(s)).collect()),
                },
            );
        }
        Value::Object(m)
    }

    pub fn from_value(v: &Value, wmts: bool) -> AppResult<TileGrid> {
        build(v, TileGrid::new_default(wmts), |t, k, val| t.apply(k, val))
    }
}

