    }

    pub fn project(&self, names: &[&str]) -> Appearance {
        let mut out = Appearance::new_default();
        for n in names {
            match *n {
                "id" => out.id = self.id,
                "attribution" => out.attribution = self.attribution.clone(),
                "hoverable" => out.hoverable = self.hoverable,
                "clickable" => out.clickable = self.clickable,
                "hoverTemplate" => out.hover_template = self.hover_template.clone(),
                "name" => out.name = self.name.clone(),
                "maxResolution" => out.max_resolution = self.max_resolution,
                "minResolution" => out.min_resolution = self.min_resolution,
                "opacity" => out.opacity = self.opacity,
                "visible" => out.visible = self.visible,
                _ => {}
            }
        }
        out
    }

    pub fn field(&self, name: &str) -> Option<FieldVal> {
        Some(match name {
            "id" => FieldVal::Int(self.id),
            "attribution" => FieldVal::Str(self.attribution.clone()),
            "hoverable" => FieldVal::Bool(self.hoverable),
            "clickable" => FieldVal::Bool(self.clickable),
            "hoverTemplate" => FieldVal::Str(self.hover_template.clone()),
            "name" => FieldVal::Str(self.name.clone()),
            "maxResolution" => FieldVal::Dbl(self.max_resolution),
            "minResolution" => FieldVal::Dbl(self.min_resolution),
            "opacity" => FieldVal::Dbl(self.opacity),
            "visible" => FieldVal::Bool(self.visible),
            _ => return None,
        })
    }

    pub fn to_json(&self) -> Value {
        obj(vec![
            ("id", j(self.id)),
            ("attribution", j(&self.attribution)),
            ("hoverable", j(self.hoverable)),
            ("clickable", j(self.clickable)),
            ("hoverTemplate", j(&self.hover_template)),
            (
                "properties",
                match &self.properties {
                    None => Value::Null,
                    Some(entries) => Value::Object(
                        entries.iter().map(|(k, v)| (k.clone(), v.to_json())).collect(),
                    ),
                },
            ),
            ("name", j(&self.name)),
            ("maxResolution", j(self.max_resolution)),
            ("minResolution", j(self.min_resolution)),
            ("opacity", j(self.opacity)),
            ("visible", j(self.visible)),
