#[derive(Clone, Debug)]
pub struct DataSource {
    pub id: Option<Id>,
    pub name: Option<String>,
    pub type_: Option<String>,
    pub url: Option<String>,
    pub format: Option<String>,
    pub kind: SourceKind,
}

impl DataSource {
    pub const FIELDS: &'static [(&'static str, FieldType)] = &[
        ("id", FieldType::Int),
        ("name", FieldType::Str),
        ("type", FieldType::Str),
        ("url", FieldType::Str),
        ("format", FieldType::Str),
    ];

    pub fn field(&self, name: &str) -> Option<FieldVal> {
        Some(match name {
            "id" => FieldVal::Int(self.id),
            "name" => FieldVal::Str(self.name.clone()),
            "type" => FieldVal::Str(self.type_.clone()),
            "url" => FieldVal::Str(self.url.clone()),
            "format" => FieldVal::Str(self.format.clone()),
            _ => return None,
        })
    }

    pub fn apply(&mut self, key: &str, v: &Value) -> AppResult<()> {
        match key {
            "id" => self.id = opt_i32(v)?,
            "name" => self.name = opt_string(v)?,
            "type" => self.type_ = opt_string(v)?,
            "url" => self.url = opt_string(v)?,
            "format" => self.format = opt_string(v)?,
            _ => {
                let handled = match &mut self.kind {
                    SourceKind::ImageWms(i) => apply_image(i, key, v)?,
                    SourceKind::TileWms(t) => apply_tile_wms(t, key, v)?,
                    SourceKind::Wfs(w) => apply_wfs(w, key, v)?,
                    SourceKind::Wmts(w) => apply_wmts(w, key, v)?,
                    SourceKind::Xyz(x) => apply_xyz(x, key, v)?,
                };
                if !handled {
                    return unknown_prop("LayerDataSource", key);
                }
            }
        }
        Ok(())
    }

    pub fn to_json(&self) -> Value {
        let mut m = obj_map(vec![
            ("id", j(self.id)),
            ("name", j(&self.name)),
            ("type", j(&self.type_)),
            ("url", j(&self.url)),
            ("format", j(&self.format)),
        ]);
        match &self.kind {
            SourceKind::ImageWms(i) => image_json(&mut m, i),
            SourceKind::TileWms(t) => {
                image_json(&mut m, &t.image);
                m.insert(
                    "tileGrid".into(),
                    t.tile_grid.as_ref().map(|g| g.to_json()).unwrap_or(Value::Null),
                );
                m.insert("requestWithTiled".into(), j(t.request_with_tiled));
            }
            SourceKind::Wfs(w) => {
                m.insert("version".into(), j(&w.version));
                m.insert("typeName".into(), j(&w.type_name));
                m.insert("typeNames".into(), j(&w.type_names));
            }
            SourceKind::Wmts(w) => {
                m.insert(
                    "tileGrid".into(),
                    w.tile_grid.as_ref().map(|g| g.to_json()).unwrap_or(Value::Null),
                );
                m.insert(
                    "urls".into(),
                    match &w.urls {
                        None => Value::Null,
                        Some(u) => Value::Array(u.iter().map(|s| j(s)).collect()),
                    },
                );
                m.insert("wmtsLayer".into(), j(&w.wmts_layer));
                m.insert("wmtsStyle".into(), j(&w.wmts_style));
                m.insert("projection".into(), j(&w.projection));
                m.insert("matrixSet".into(), j(&w.matrix_set));
                m.insert("requestEncoding".into(), j(&w.request_encoding));
                m.insert("capabilitiesUrl".into(), j(&w.capabilities_url));
            }
            SourceKind::Xyz(x) => {
                m.insert("center".into(), point_json(&x.center));
                m.insert(
                    "extent".into(),
                    x.extent.as_ref().map(|e| e.to_json()).unwrap_or(Value::Null),
                );
                m.insert("resolutions".into(), f64_list_json(&x.resolutions));
                m.insert("tileSize".into(), j(x.tile_size));
            }
        }
        Value::Object(m)
    }
}

fn image_json(m: &mut Map<String, Value>, i: &ImageWms) {
    m.insert("width".into(), j(i.width));
    m.insert("height".into(), j(i.height));
    m.insert("version".into(), j(&i.version));
    m.insert("layerNames".into(), j(&i.layer_names));
    m.insert("layerStyles".into(), j(&i.layer_styles));
    m.insert("requestableByPath".into(), j(i.requestable_by_path));
    m.insert("customRequestPath".into(), j(&i.custom_request_path));
}

fn apply_image(i: &mut ImageWms, key: &str, v: &Value) -> AppResult<bool> {
    match key {
        "width" => i.width = prim_i32(v)?,
        "height" => i.height = prim_i32(v)?,
        "version" => i.version = opt_string(v)?,
        "layerNames" => i.layer_names = opt_string(v)?,
        "layerStyles" => i.layer_styles = opt_string(v)?,
        "requestableByPath" => i.requestable_by_path = opt_bool(v)?,
        "customRequestPath" => i.custom_request_path = opt_string(v)?,
        _ => return Ok(false),
    }
    Ok(true)
}

fn apply_tile_wms(t: &mut TileWms, key: &str, v: &Value) -> AppResult<bool> {
    if apply_image(&mut t.image, key, v)? {
        return Ok(true);
    }
    match key {
        "tileGrid" => {
            t.tile_grid = match v {
                Value::Null => None,
                _ => Some(TileGrid::from_value(v, false)?),
            }
        }
        "requestWithTiled" => t.request_with_tiled = opt_bool(v)?,
        _ => return Ok(false),
    }
    Ok(true)
}

fn apply_wfs(w: &mut Wfs, key: &str, v: &Value) -> AppResult<bool> {
    match key {
        "version" => w.version = opt_string(v)?,
        "typeName" => w.type_name = opt_string(v)?,
        "typeNames" => w.type_names = opt_string(v)?,
        _ => return Ok(false),
    }
    Ok(true)
}

fn apply_wmts(w: &mut Wmts, key: &str, v: &Value) -> AppResult<bool> {
    match key {
        "tileGrid" => {
            w.tile_grid = match v {
                Value::Null => None,
                _ => Some(TileGrid::from_value(v, true)?),
            }
        }
        "urls" => w.urls = opt_string_list(v)?,
        "wmtsLayer" => w.wmts_layer = opt_string(v)?,
        "wmtsStyle" => w.wmts_style = opt_string(v)?,
        "projection" => w.projection = opt_string(v)?,
        "matrixSet" => w.matrix_set = opt_string(v)?,
        "requestEncoding" => w.request_encoding = opt_string(v)?,
        "capabilitiesUrl" => w.capabilities_url = opt_string(v)?,
        _ => return Ok(false),
    }
    Ok(true)
}

fn apply_xyz(x: &mut Xyz, key: &str, v: &Value) -> AppResult<bool> {
    match key {
        "center" => x.center = point_from(v)?,
        "extent" => {
            x.extent = match v {
                Value::Null => None,
                _ => Some(Extent::from_value(v)?),
            }
        }
        "resolutions" => x.resolutions = opt_f64_list(v)?,
        "tileSize" => x.tile_size = opt_i32(v)?,
        _ => return Ok(false),
    }
    Ok(true)
}

