}

impl Layer {
    pub const FIELDS: &'static [(&'static str, FieldType)] = &[
        ("id", FieldType::Int),
        ("name", FieldType::Str),
        ("description", FieldType::Str),
    ];

    pub fn apply(&mut self, key: &str, v: &Value) -> AppResult<()> {
        match key {
            "id" => self.id = opt_i32(v)?,
            "name" => self.name = opt_string(v)?,
            "description" => self.description = opt_string(v)?,
            // LayerDataSource is abstract: Jackson cannot build it.
            "source" => match v {
                Value::Null => self.source = None,
                _ => return json_err("Cannot construct instance of LayerDataSource (abstract)"),
            },
            "appearance" => {
                self.appearance = match v {
                    Value::Null => None,
                    _ => Some(Appearance::from_value(v)?),
                }
            }
            _ => return unknown_prop("Layer", key),
        }
        Ok(())
    }

    pub fn project(&self, names: &[&str]) -> Layer {
        let mut out = Layer::default();
        for n in names {
            match *n {
                "id" => out.id = self.id,
                "name" => out.name = self.name.clone(),
                "description" => out.description = self.description.clone(),
                _ => {}
            }
        }
        out
    }

    pub fn field(&self, name: &str) -> Option<FieldVal> {
        Some(match name {
            "id" => FieldVal::Int(self.id),
            "name" => FieldVal::Str(self.name.clone()),
            "description" => FieldVal::Str(self.description.clone()),
            _ => return None,
        })
    }

    pub fn to_json(&self) -> Value {
        obj(vec![
            ("id", j(self.id)),
            ("name", j(&self.name)),
            ("description", j(&self.description)),
            ("source", self.source.as_ref().map(|s| s.to_json()).unwrap_or(Value::Null)),
            (
                "appearance",
                self.appearance.as_ref().map(|a| a.to_json()).unwrap_or(Value::Null),
            ),
        ])
    }

    pub fn from_value(v: &Value) -> AppResult<Layer> {
        build(v, Layer::default(), |t, k, val| t.apply(k, val))
    }
}

// ---------------------------------------------------------------- Ent

/// Any entity of the slice, for the generic endpoints.
#[derive(Clone, Debug)]
pub enum Ent {
    User(User),
    Group(UserGroup),
    Role(Role),
    Layer(Layer),
    Source(DataSource),
    Appearance(Appearance),
}

impl Ent {
    pub fn kind(&self) -> Kind {
        match self {
            Ent::User(_) => Kind::User,
            Ent::Group(_) => Kind::Group,
            Ent::Role(_) => Kind::Role,
            Ent::Layer(_) => Kind::Layer,
            Ent::Source(_) => Kind::Source,
            Ent::Appearance(_) => Kind::Appearance,
        }
    }

    pub fn id(&self) -> Option<Id> {
        match self {
            Ent::User(e) => e.id,
            Ent::Group(e) => e.id,
            Ent::Role(e) => e.id,
            Ent::Layer(e) => e.id,
            Ent::Source(e) => e.id,
            Ent::Appearance(e) => e.id,
        }
    }

    pub fn fields(kind: Kind) -> &'static [(&'static str, FieldType)] {
        match kind {
            Kind::User => User::FIELDS,
            Kind::Group => UserGroup::FIELDS,
            Kind::Role => Role::FIELDS,
            Kind::Layer => Layer::FIELDS,
            Kind::Source => DataSource::FIELDS,
            Kind::Appearance => Appearance::FIELDS,
        }
    }

    /// The default-constructed object of a kind, for POST.
    pub fn new_default(kind: Kind) -> AppResult<Ent> {
        Ok(match kind {
            Kind::User => Ent::User(User::new_default()),
            Kind::Group => Ent::Group(UserGroup::new_default()),
            Kind::Role => Ent::Role(Role::default()),
            Kind::Layer => Ent::Layer(Layer::default()),
            Kind::Appearance => Ent::Appearance(Appearance::new_default()),
            Kind::Source => return json_err("LayerDataSource is abstract"),
        })
    }

    pub fn apply(&mut self, key: &str, v: &Value) -> AppResult<()> {
        match self {
            Ent::User(e) => e.apply(key, v),
            Ent::Group(e) => e.apply(key, v),
            Ent::Role(e) => e.apply(key, v),
            Ent::Layer(e) => e.apply(key, v),
            Ent::Source(e) => e.apply(key, v),
            Ent::Appearance(e) => e.apply(key, v),
        }
    }

    pub fn project(&self, names: &[&str]) -> Ent {
        match self {
            Ent::User(e) => Ent::User(e.project(names)),
            Ent::Group(e) => Ent::Group(e.project(names)),
            Ent::Role(e) => {
                let mut out = Role::default();
                for n in names {
                    match *n {
                        "id" => out.id = e.id,
                        "name" => out.name = e.name.clone(),
                        "description" => out.description = e.description.clone(),
                        _ => {}
                    }
                }
                Ent::Role(out)
            }
            Ent::Layer(e) => Ent::Layer(e.project(names)),
            Ent::Source(e) => {
                // Not reached: the original cannot project abstract sources.
                let mut out = e.clone();
                out.name = None;
                Ent::Source(out)
            }
            Ent::Appearance(e) => Ent::Appearance(e.project(names)),
        }
    }

    pub fn field(&self, name: &str) -> Option<FieldVal> {
        match self {
            Ent::User(e) => e.field(name),
            Ent::Group(e) => e.field(name),
            Ent::Role(e) => match name {
                "id" => Some(FieldVal::Int(e.id)),
                "name" => Some(FieldVal::Str(e.name.clone())),
                "description" => Some(FieldVal::Str(e.description.clone())),
                _ => None,
            },
            Ent::Layer(e) => e.field(name),
            Ent::Source(e) => e.field(name),
            Ent::Appearance(e) => e.field(name),
        }
    }

    pub fn to_json(&self) -> Value {
        match self {
            Ent::User(e) => e.to_json(),
            Ent::Group(e) => e.to_json(),
            Ent::Role(e) => e.to_json(),
            Ent::Layer(e) => e.to_json(),
            Ent::Source(e) => e.to_json(),
            Ent::Appearance(e) => e.to_json(),
        }
    }

    pub fn set_id(&mut self, id: Id) {
        match self {
            Ent::User(e) => e.id = Some(id),
            Ent::Group(e) => e.id = Some(id),
            Ent::Role(e) => e.id = Some(id),
            Ent::Layer(e) => e.id = Some(id),
            Ent::Source(e) => e.id = Some(id),
            Ent::Appearance(e) => e.id = Some(id),
        }
    }
}

/// Keys Jackson ignores on every entity (`@JsonIgnore` on the base class).
pub fn is_ignored_key(key: &str) -> bool {
    matches!(key, "created" | "modified" | "userPermissions" | "groupPermissions")
}

/// Applies a JSON object to a default object in key order, the way
/// Jackson's bean deserialiser does.
pub fn build<T>(
    v: &Value,
    mut t: T,
    apply: impl Fn(&mut T, &str, &Value) -> AppResult<()>,
) -> AppResult<T> {
    match v {
        Value::Object(o) => {
            for (k, val) in o {
                if is_ignored_key(k) {
                    continue;
                }
                apply(&mut t, k, val)?;
            }
            Ok(t)
        }
        _ => json_err("expected a JSON object"),
    }
}

pub fn unknown_prop<T>(ty: &str, key: &str) -> AppResult<T> {
    json_err(format!("Unrecognized field \"{key}\" (class {ty})"))
}

// ---------------------------------------------------------------- JSON helpers

pub fn j<T: serde::Serialize>(t: T) -> Value {
    serde_json::to_value(t).unwrap_or(Value::Null)
}

pub fn obj(pairs: Vec<(&str, Value)>) -> Value {
    Value::Object(obj_map(pairs))
}

pub fn obj_map(pairs: Vec<(&str, Value)>) -> Map<String, Value> {
    let mut m = Map::new();
    for (k, v) in pairs {
        m.insert(k.to_string(), v);
    }
    m
}

pub fn roles_json(roles: &Option<Vec<Role>>) -> Value {
    match roles {
        None => Value::Null,
        Some(rs) => Value::Array(rs.iter().map(|r| r.to_json()).collect()),
    }
}

pub fn f64_list_json(list: &Option<Vec<f64>>) -> Value {
    match list {
        None => Value::Null,
        Some(vs) => Value::Array(
            vs.iter()
                .map(|d| serde_json::Number::from_f64(*d).map(Value::Number).unwrap_or(Value::Null))
                .collect(),
        ),
    }
}

tool_use_result.content:
//! The entities of the slice, as the Java object graph holds them.
//!
//! * `Option` means "may be null in Java".
//! * A collection of `Some(vec)` is a loaded or default-constructed
//!   collection; `None` is a `null` collection (for example `"roles": null`).
//! * Nested objects keep exactly what was read, so a response echoes the
//!   in-memory object just as Jackson serialises the Java one.

use chrono::NaiveDate;
use serde_json::{Map, Value};

use crate::err::{json_err, AppResult};
use crate::jsonx::*;

pub type Id = i32;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Kind {
    User,
    Group,
    Role,
    Layer,
    Source,
    Appearance,
}

/// Field value kinds, used for filters and `output:only`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FieldType {
    Str,
    Int,
    Bool,
    Dbl,
}

#[derive(Clone, Debug, PartialEq)]
pub enum FieldVal {
    Str(Option<String>),
    Int(Option<i32>),
    Bool(Option<bool>),
    Dbl(Option<f64>),
}

#[derive(Clone, Debug, Default, PartialEq)]
pub struct Point {
    pub x: f64,
    pub y: f64,
}

#[derive(Clone, Debug, PartialEq)]
pub enum PropValue {
    Null,
    Bool(bool),
    Int(i64),
    Double(f64),
    Str(String),
    List(Vec<PropValue>),
    Map(Vec<(String, PropValue)>),
}

// ---------------------------------------------------------------- Role

#[derive(Clone, Debug, Default)]
pub struct Role {
    pub id: Option<Id>,
    pub name: Option<String>,
    pub description: Option<String>,
}

impl Role {
    pub const FIELDS: &'static [(&'static str, FieldType)] = &[
        ("id", FieldType::Int),
        ("name", FieldType::Str),
        ("description", FieldType::Str),
    ];

    pub fn apply(&mut self, key: &str, v: &Value) -> AppResult<()> {
        match key {
            "id" => self.id = opt_i32(v)?,
            "name" => self.name = opt_string(v)?,
            "description" => self.description = opt_string(v)?,
            _ => return unknown_prop("Role", key),
        }
        Ok(())
    }

    pub fn to_json(&self) -> Value {
        obj(vec![
            ("id", j(self.id)),
            ("name", j(&self.name)),
            ("description", j(&self.description)),
        ])
    }

    pub fn from_value(v: &Value) -> AppResult<Role> {
        build(v, Role::default(), |t, k, val| t.apply(k, val))
    }
}

// ---------------------------------------------------------------- User

#[derive(Clone, Debug, Default)]
pub struct GroupRef {
    /// The group id; `None` is a transient or null reference.
    pub id: Option<Id>,
    /// A plain id in the JSON; it has to be resolved with a READ check.
    pub resolve: bool,
}

#[derive(Clone, Debug, Default)]
pub struct User {
    pub id: Option<Id>,
    pub first_name: Option<String>,
    pub last_name: Option<String>,
    pub email: Option<String>,
    pub birthday: Option<NaiveDate>,
    pub language: Option<String>,
    pub account_name: Option<String>,
    pub password: Option<String>,
    pub active: bool,
    pub roles: Option<Vec<Role>>,
    pub user_groups: Option<Vec<GroupRef>>,
}

impl User {
    pub const FIELDS: &'static [(&'static str, FieldType)] = &[
        ("id", FieldType::Int),
        ("firstName", FieldType::Str),
        ("lastName", FieldType::Str),
        ("email", FieldType::Str),
        ("accountName", FieldType::Str),
        ("password", FieldType::Str),
        ("active", FieldType::Bool),
    ];

    /// The constructor Jackson calls: `active` false, empty collections.
    pub fn new_default() -> User {
        User {
            roles: Some(vec![]),
            user_groups: Some(vec![]),
            ..Default::default()
        }
    }

    pub fn apply(&mut self, key: &str, v: &Value) -> AppResult<()> {
        match key {
            "id" => self.id = opt_i32(v)?,
            "firstName" => self.first_name = opt_string(v)?,
            "lastName" => self.last_name = opt_string(v)?,
            "email" => self.email = opt_string(v)?,
            "birthday" => self.birthday = opt_date(v)?,
            "language" => self.language = opt_locale(v)?,
            "accountName" => self.account_name = opt_string(v)?,
            "password" => self.password = opt_string(v)?,
            "active" => self.active = prim_bool(v)?,
            "roles" => {
                self.roles = match opt_array(v)? {
                    None => None,
                    Some(items) => Some(items.iter().map(Role::from_value).collect::<AppResult<_>>()?),
                }
            }
            "userGroups" => {
                self.user_groups = match opt_array(v)? {
                    None => None,
                    Some(items) => Some(items.iter().map(group_ref).collect::<AppResult<_>>()?),
                }
            }
            _ => return unknown_prop("User", key),
        }
        Ok(())
    }

    /// Copies only the restricted fields onto a default-constructed object.
    pub fn project(&self, names: &[&str]) -> User {
        let mut out = User::new_default();
        for n in names {
            match *n {
                "id" => out.id = self.id,
                "firstName" => out.first_name = self.first_name.clone(),
                "lastName" => out.last_name = self.last_name.clone(),
                "email" => out.email = self.email.clone(),
                "accountName" => out.account_name = self.account_name.clone(),
                "password" => out.password = self.password.clone(),
                "active" => out.active = self.active,
                _ => {}
            }
        }
        out
    }

    pub fn field(&self, name: &str) -> Option<FieldVal> {
        Some(match name {
            "id" => FieldVal::Int(self.id),
            "firstName" => FieldVal::Str(self.first_name.clone()),
            "lastName" => FieldVal::Str(self.last_name.clone()),
            "email" => FieldVal::Str(self.email.clone()),
            "accountName" => FieldVal::Str(self.account_name.clone()),
            "password" => FieldVal::Str(self.password.clone()),
            "active" => FieldVal::Bool(Some(self.active)),
            _ => return None,
        })
    }

    pub fn to_json(&self) -> Value {
        obj(vec![
            ("id", j(self.id)),
            ("firstName", j(&self.first_name)),
            ("lastName", j(&self.last_name)),
            ("email", j(&self.email)),
            ("birthday", j(self.birthday.map(|d| d.format("%Y-%m-%d").to_string()))),
            ("language", j(&self.language)),
            ("accountName", j(&self.account_name)),
            ("active", j(self.active)),
            ("roles", roles_json(&self.roles)),
            (
                "userGroups",
                match &self.user_groups {
                    None => Value::Null,
                    Some(refs) => Value::Array(refs.iter().map(|g| j(g.id)).collect()),
                },
            ),
        ])
    }

    pub fn from_value(v: &Value) -> AppResult<User> {
        build(v, User::new_default(), |t, k, val| t.apply(k, val))
    }
}

fn group_ref(v: &Value) -> AppResult<GroupRef> {
    match v {
        Value::Null => Ok(GroupRef { id: None, resolve: false }),
        Value::Object(_) => {
            // An object is deserialised as a whole UserGroup; only its id is
            // used for the reference.
            let g = UserGroup::from_value(v)?;
            Ok(GroupRef { id: g.id, resolve: false })
        }
        _ => Ok(GroupRef { id: opt_i32(v)?, resolve: true }),
    }
}

// ---------------------------------------------------------------- UserGroup

#[derive(Clone, Debug, Default)]
pub struct UserGroup {
    pub id: Option<Id>,
    pub name: Option<String>,
    pub owner: Option<User>,
    pub members: Option<Vec<User>>,
    pub roles: Option<Vec<Role>>,
}

impl UserGroup {
    pub const FIELDS: &'static [(&'static str, FieldType)] =
        &[("id", FieldType::Int), ("name", FieldType::Str)];

    pub fn new_default() -> UserGroup {
        UserGroup {
            members: Some(vec![]),
            roles: Some(vec![]),
            ..Default::default()
        }
    }

    pub fn apply(&mut self, key: &str, v: &Value) -> AppResult<()> {
        match key {
            "id" => self.id = opt_i32(v)?,
            "name" => self.name = opt_string(v)?,
            "owner" => {
                self.owner = match v {
                    Value::Null => None,
                    _ => Some(User::from_value(v)?),
                }
            }
            "members" => {
                self.members = match opt_array(v)? {
                    None => None,
                    Some(items) => Some(items.iter().map(User::from_value).collect::<AppResult<_>>()?),
                }
            }
            "roles" => {
                self.roles = match opt_array(v)? {
                    None => None,
                    Some(items) => Some(items.iter().map(Role::from_value).collect::<AppResult<_>>()?),
                }
            }
            _ => return unknown_prop("UserGroup", key),
        }
        Ok(())
    }

    pub fn project(&self, names: &[&str]) -> UserGroup {
        let mut out = UserGroup::new_default();
        for n in names {
            match *n {
                "id" => out.id = self.id,
                "name" => out.name = self.name.clone(),
                _ => {}
            }
        }
        out
    }

    pub fn field(&self, name: &str) -> Option<FieldVal> {
        Some(match name {
            "id" => FieldVal::Int(self.id),
            "name" => FieldVal::Str(self.name.clone()),
            _ => return None,
        })
    }

    pub fn to_json(&self) -> Value {
        obj(vec![
            ("id", j(self.id)),
            ("name", j(&self.name)),
            ("owner", self.owner.as_ref().map(|u| u.to_json()).unwrap_or(Value::Null)),
            (
                "members",
                match &self.members {
                    None => Value::Null,
                    Some(ms) => Value::Array(ms.iter().map(|m| m.to_json()).collect()),
                },
            ),
            ("roles", roles_json(&self.roles)),
        ])
    }

    pub fn from_value(v: &Value) -> AppResult<UserGroup> {
        build(v, UserGroup::new_default(), |t, k, val| t.apply(k, val))
    }
}

// ---------------------------------------------------------------- Extent / Point / TileGrid

#[derive(Clone, Debug, Default)]
pub struct Extent {
    pub id: Option<Id>,
    pub lower_left: Option<Point>,
    pub upper_right: Option<Point>,
}

impl Extent {
    pub fn apply(&mut self, key: &str, v: &Value) -> AppResult<()> {
        match key {
            "id" => self.id = opt_i32(v)?,
            "lowerLeft" => self.lower_left = point_from(v)?,
            "upperRight" => self.upper_right = point_from(v)?,
            _ => return unknown_prop("Extent", key),
        }
        Ok(())
    }

    pub fn to_json(&self) -> Value {
        obj(vec![
            ("id", j(self.id)),
            ("lowerLeft", point_json(&self.lower_left)),
            ("upperRight", point_json(&self.upper_right)),
        ])
    }

    pub fn from_value(v: &Value) -> AppResult<Extent> {
        build(v, Extent::default(), |t, k, val| t.apply(k, val))
    }
}

pub fn point_from(v: &Value) -> AppResult<Option<Point>> {
    match v {
        Value::Null => Ok(None),
        Value::Object(o) => {
            let mut p = Point::default();
            for (k, val) in o {
                match k.as_str() {
                    "x" => p.x = prim_f64(val)?,
                    "y" => p.y = prim_f64(val)?,
                    _ => return unknown_prop("Point2D.Double", k),
                }
            }
            Ok(Some(p))
        }
        _ => json_err("cannot deserialize Point2D.Double"),
    }
}

pub fn point_json(p: &Option<Point>) -> Value {
    match p {
        None => Value::Null,
        Some(p) => obj(vec![("x", j(p.x)), ("y", j(p.y))]),
    }
}

#[derive(Clone, Debug, Default)]
pub struct TileGrid {
    pub id: Option<Id>,
    pub type_: Option<String>,
    pub origin: Option<Point>,
    pub extent: Option<Extent>,
    pub tile_size: Option<i32>,
    pub resolutions: Option<Vec<f64>>,
    /// True for a `WmtsTileGrid` (a row in `wmtstilegrids` exists).
    pub wmts: bool,
    pub matrix_ids: Option<Vec<String>>,
}

impl TileGrid {
    /// The Jackson constructor sets the tile size to 256.
    pub fn new_default(wmts: bool) -> TileGrid {
        TileGrid {
            tile_size: Some(256),
            wmts,
            ..Default::default()
        }
    }

    pub fn apply(&mut self, key: &str, v: &Value) -> AppResult<()> {
        match key {
            "id" => self.id = opt_i32(v)?,
            "type" => self.type_ = opt_string(v)?,
            "tileGridOrigin" => self.origin = point_from(v)?,
            "tileGridExtent" => {
                self.extent = match v {
                    Value::Null => None,
                    _ => Some(Extent::from_value(v)?),
                }
            }
            "tileSize" => self.tile_size = opt_i32(v)?,
            "tileGridResolutions" => self.resolutions = opt_f64_list(v)?,
            "matrixIds" if self.wmts => self.matrix_ids = opt_string_list(v)?,
            _ => return unknown_prop("TileGrid", key),
        }
        Ok(())
    }

    pub fn to_json(&self) -> Value {
        let mut m = obj_map(vec![
            ("id", j(self.id)),
            ("type", j(&self.type_)),
            ("tileGridOrigin", point_json(&self.origin)),
            (
                "tileGridExtent",
                self.extent.as_ref().map(|e| e.to_json()).unwrap_or(Value::Null),
            ),
            ("tileSize", j(self.tile_size)),
            ("tileGridResolutions", f64_list_json(&self.resolutions)),
        ]);
        if self.wmts {
            m.insert(
                "matrixIds".into(),
                match &self.matrix_ids {
                    None => Value::Null,
                    Some(ids) => Value::Array(ids.iter().map(|s| j(s)).collect()),
                },
            );
        }
        Value::Object(m)
    }

    pub fn from_value(v: &Value, wmts: bool) -> AppResult<TileGrid> {
        build(v, TileGrid::new_default(wmts), |t, k, val| t.apply(k, val))
    }
}

// ---------------------------------------------------------------- LayerAppearance

#[derive(Clone, Debug, Default)]
pub struct Appearance {
    pub id: Option<Id>,
    pub attribution: Option<String>,
    pub hoverable: Option<bool>,
    pub clickable: Option<bool>,
    pub hover_template: Option<String>,
    pub properties: Option<Vec<(String, PropValue)>>,
    pub name: Option<String>,
    pub max_resolution: Option<f64>,
    pub min_resolution: Option<f64>,
    pub opacity: Option<f64>,
    pub visible: Option<bool>,
}

impl Appearance {
    pub const FIELDS: &'static [(&'static str, FieldType)] = &[
        ("id", FieldType::Int),
        ("attribution", FieldType::Str),
        ("hoverable", FieldType::Bool),
        ("clickable", FieldType::Bool),
        ("hoverTemplate", FieldType::Str),
        ("name", FieldType::Str),
        ("maxResolution", FieldType::Dbl),
        ("minResolution", FieldType::Dbl),
        ("opacity", FieldType::Dbl),
        ("visible", FieldType::Bool),
    ];

    pub fn new_default() -> Appearance {
        Appearance {
            properties: Some(vec![]),
            ..Default::default()
        }
    }

    pub fn apply(&mut self, key: &str, v: &Value) -> AppResult<()> {
        match key {
            "id" => self.id = opt_i32(v)?,
            "attribution" => self.attribution = opt_string(v)?,
            "hoverable" => self.hoverable = opt_bool(v)?,
            "clickable" => self.clickable = opt_bool(v)?,
            "hoverTemplate" => self.hover_template = opt_string(v)?,
            "properties" => {
                self.properties = match opt_object(v)? {
                    None => None,
                    Some(o) => Some(
                        o.iter()
                            .map(|(k, val)| Ok((k.clone(), PropValue::from_json(val))))
                            .collect::<AppResult<_>>()?,
                    ),
                }
            }
            "name" => self.name = opt_string(v)?,
            "maxResolution" => self.max_resolution = opt_f64(v)?,
            "minResolution" => self.min_resolution = opt_f64(v)?,
            "opacity" => self.opacity = opt_f64(v)?,
            "visible" => self.visible = opt_bool(v)?,
            _ => return unknown_prop("LayerAppearance", key),
        }
        Ok(())
    }

    pub fn project(&self, names: &[&str]) -> Appearance {
        let mut out = Appearance::new_default();
        for n in names {
            match *n {
                "id" => out.id = self.id,
                "attribution" => out.attribution = self.attribution.clone(),
                "hoverable" => out.hoverable = self.hoverable,
                "clickable" => out.clickable = self.clickable,
                "hoverTemplate" => out.hover_template = self.hover_template.clone(),
                "name" => out.name = self.name.clone(),
                "maxResolution" => out.max_resolution = self.max_resolution,
                "minResolution" => out.min_resolution = self.min_resolution,
                "opacity" => out.opacity = self.opacity,
                "visible" => out.visible = self.visible,
                _ => {}
            }
        }
        out
    }

    pub fn field(&self, name: &str) -> Option<FieldVal> {
        Some(match name {
            "id" => FieldVal::Int(self.id),
            "attribution" => FieldVal::Str(self.attribution.clone()),
            "hoverable" => FieldVal::Bool(self.hoverable),
            "clickable" => FieldVal::Bool(self.clickable),
            "hoverTemplate" => FieldVal::Str(self.hover_template.clone()),
            "name" => FieldVal::Str(self.name.clone()),
            "maxResolution" => FieldVal::Dbl(self.max_resolution),
            "minResolution" => FieldVal::Dbl(self.min_resolution),
            "opacity" => FieldVal::Dbl(self.opacity),
            "visible" => FieldVal::Bool(self.visible),
            _ => return None,
        })
    }

    pub fn to_json(&self) -> Value {
        obj(vec![
            ("id", j(self.id)),
            ("attribution", j(&self.attribution)),
            ("hoverable", j(self.hoverable)),
            ("clickable", j(self.clickable)),
            ("hoverTemplate", j(&self.hover_template)),
            (
                "properties",
                match &self.properties {
                    None => Value::Null,
                    Some(entries) => Value::Object(
                        entries.iter().map(|(k, v)| (k.clone(), v.to_json())).collect(),
                    ),
                },
            ),
            ("name", j(&self.name)),
            ("maxResolution", j(self.max_resolution)),
            ("minResolution", j(self.min_resolution)),
            ("opacity", j(self.opacity)),
            ("visible", j(self.visible)),
        ])
    }

    pub fn from_value(v: &Value) -> AppResult<Appearance> {
        build(v, Appearance::new_default(), |t, k, val| t.apply(k, val))
    }
}

impl PropValue {
    /// Jackson's `Object` mapping of a JSON value.
    pub fn from_json(v: &Value) -> PropValue {
        match v {
            Value::Null => PropValue::Null,
            Value::Bool(b) => PropValue::Bool(*b),
            Value::Number(n) => match n.as_i64() {
                Some(i) if !n.is_f64() => PropValue::Int(i),
                _ => PropValue::Double(n.as_f64().unwrap_or(0.0)),
            },
            Value::String(s) => PropValue::Str(s.clone()),
            Value::Array(items) => PropValue::List(items.iter().map(PropValue::from_json).collect()),
            Value::Object(o) => PropValue::Map(
                o.iter().map(|(k, v)| (k.clone(), PropValue::from_json(v))).collect(),
            ),
        }
    }

    pub fn to_json(&self) -> Value {
        match self {
            PropValue::Null => Value::Null,
            PropValue::Bool(b) => Value::Bool(*b),
            PropValue::Int(i) => Value::from(*i),
            PropValue::Double(d) => serde_json::Number::from_f64(*d)
                .map(Value::Number)
                .unwrap_or(Value::Null),
            PropValue::Str(s) => Value::String(s.clone()),
            PropValue::List(items) => Value::Array(items.iter().map(|i| i.to_json()).collect()),
            PropValue::Map(entries) => Value::Object(
                entries.iter().map(|(k, v)| (k.clone(), v.to_json())).collect(),
            ),
        }
    }
}

// ---------------------------------------------------------------- LayerDataSource

#[derive(Clone, Debug, Default)]
pub struct ImageWms {
    pub width: i32,
    pub height: i32,
    pub version: Option<String>,
    pub layer_names: Option<String>,
    pub layer_styles: Option<String>,
    pub requestable_by_path: Option<bool>,
    pub custom_request_path: Option<String>,
}

#[derive(Clone, Debug, Default)]
pub struct TileWms {
    pub image: ImageWms,
    pub tile_grid: Option<TileGrid>,
    pub request_with_tiled: Option<bool>,
}

#[derive(Clone, Debug, Default)]
pub struct Wfs {
    pub version: Option<String>,
    pub type_name: Option<String>,
    pub type_names: Option<String>,
}

#[derive(Clone, Debug, Default)]
pub struct Wmts {
    pub tile_grid: Option<TileGrid>,
    pub urls: Option<Vec<String>>,
    pub wmts_layer: Option<String>,
    pub wmts_style: Option<String>,
    pub projection: Option<String>,
    pub matrix_set: Option<String>,
    pub request_encoding: Option<String>,
    pub capabilities_url: Option<String>,
}

#[derive(Clone, Debug, Default)]
pub struct Xyz {
    pub center: Option<Point>,
    pub extent: Option<Extent>,
    pub resolutions: Option<Vec<f64>>,
    pub tile_size: Option<i32>,
}

#[derive(Clone, Debug)]
pub enum SourceKind {
    ImageWms(ImageWms),
    TileWms(TileWms),
    Wfs(Wfs),
    Wmts(Wmts),
    Xyz(Xyz),
}

#[derive(Clone, Debug)]
pub struct DataSource {
    pub id: Option<Id>,
    pub name: Option<String>,
    pub type_: Option<String>,
    pub url: Option<String>,
    pub format: Option<String>,
    pub kind: SourceKind,
}

impl DataSource {
    pub const FIELDS: &'static [(&'static str, FieldType)] = &[
        ("id", FieldType::Int),
        ("name", FieldType::Str),
        ("type", FieldType::Str),
        ("url", FieldType::Str),
        ("format", FieldType::Str),
    ];

    pub fn field(&self, name: &str) -> Option<FieldVal> {
        Some(match name {
            "id" => FieldVal::Int(self.id),
            "name" => FieldVal::Str(self.name.clone()),
            "type" => FieldVal::Str(self.type_.clone()),
            "url" => FieldVal::Str(self.url.clone()),
            "format" => FieldVal::Str(self.format.clone()),
            _ => return None,
        })
    }

    pub fn apply(&mut self, key: &str, v: &Value) -> AppResult<()> {
        match key {
            "id" => self.id = opt_i32(v)?,
            "name" => self.name = opt_string(v)?,
            "type" => self.type_ = opt_string(v)?,
            "url" => self.url = opt_string(v)?,
            "format" => self.format = opt_string(v)?,
            _ => {
                let handled = match &mut self.kind {
                    SourceKind::ImageWms(i) => apply_image(i, key, v)?,
                    SourceKind::TileWms(t) => apply_tile_wms(t, key, v)?,
                    SourceKind::Wfs(w) => apply_wfs(w, key, v)?,
                    SourceKind::Wmts(w) => apply_wmts(w, key, v)?,
                    SourceKind::Xyz(x) => apply_xyz(x, key, v)?,
                };
                if !handled {
                    return unknown_prop("LayerDataSource", key);
                }
            }
        }
        Ok(())
    }

    pub fn to_json(&self) -> Value {
        let mut m = obj_map(vec![
            ("id", j(self.id)),
            ("name", j(&self.name)),
            ("type", j(&self.type_)),
            ("url", j(&self.url)),
            ("format", j(&self.format)),
        ]);
        match &self.kind {
            SourceKind::ImageWms(i) => image_json(&mut m, i),
            SourceKind::TileWms(t) => {
                image_json(&mut m, &t.image);
                m.insert(
                    "tileGrid".into(),
                    t.tile_grid.as_ref().map(|g| g.to_json()).unwrap_or(Value::Null),
                );
                m.insert("requestWithTiled".into(), j(t.request_with_tiled));
            }
            SourceKind::Wfs(w) => {
                m.insert("version".into(), j(&w.version));
                m.insert("typeName".into(), j(&w.type_name));
                m.insert("typeNames".into(), j(&w.type_names));
            }
            SourceKind::Wmts(w) => {
                m.insert(
                    "tileGrid".into(),
                    w.tile_grid.as_ref().map(|g| g.to_json()).unwrap_or(Value::Null),
                );
                m.insert(
                    "urls".into(),
                    match &w.urls {
                        None => Value::Null,
                        Some(u) => Value::Array(u.iter().map(|s| j(s)).collect()),
                    },
                );
                m.insert("wmtsLayer".into(), j(&w.wmts_layer));
                m.insert("wmtsStyle".into(), j(&w.wmts_style));
                m.insert("projection".into(), j(&w.projection));
                m.insert("matrixSet".into(), j(&w.matrix_set));
                m.insert("requestEncoding".into(), j(&w.request_encoding));
                m.insert("capabilitiesUrl".into(), j(&w.capabilities_url));
            }
            SourceKind::Xyz(x) => {
                m.insert("center".into(), point_json(&x.center));
                m.insert(
                    "extent".into(),
                    x.extent.as_ref().map(|e| e.to_json()).unwrap_or(Value::Null),
                );
                m.insert("resolutions".into(), f64_list_json(&x.resolutions));
                m.insert("tileSize".into(), j(x.tile_size));
            }
        }
        Value::Object(m)
    }
}

fn image_json(m: &mut Map<String, Value>, i: &ImageWms) {
    m.insert("width".into(), j(i.width));
    m.insert("height".into(), j(i.height));
    m.insert("version".into(), j(&i.version));
    m.insert("layerNames".into(), j(&i.layer_names));
    m.insert("layerStyles".into(), j(&i.layer_styles));
    m.insert("requestableByPath".into(), j(i.requestable_by_path));
    m.insert("customRequestPath".into(), j(&i.custom_request_path));
}

fn apply_image(i: &mut ImageWms, key: &str, v: &Value) -> AppResult<bool> {
    match key {
        "width" => i.width = prim_i32(v)?,
        "height" => i.height = prim_i32(v)?,
        "version" => i.version = opt_string(v)?,
        "layerNames" => i.layer_names = opt_string(v)?,
        "layerStyles" => i.layer_styles = opt_string(v)?,
        "requestableByPath" => i.requestable_by_path = opt_bool(v)?,
        "customRequestPath" => i.custom_request_path = opt_string(v)?,
        _ => return Ok(false),
    }
    Ok(true)
}

fn apply_tile_wms(t: &mut TileWms, key: &str, v: &Value) -> AppResult<bool> {
    if apply_image(&mut t.image, key, v)? {
        return Ok(true);
    }
    match key {
        "tileGrid" => {
            t.tile_grid = match v {
                Value::Null => None,
                _ => Some(TileGrid::from_value(v, false)?),
            }
        }
        "requestWithTiled" => t.request_with_tiled = opt_bool(v)?,
        _ => return Ok(false),
    }
    Ok(true)
}

fn apply_wfs(w: &mut Wfs, key: &str, v: &Value) -> AppResult<bool> {
    match key {
        "version" => w.version = opt_string(v)?,
        "typeName" => w.type_name = opt_string(v)?,
        "typeNames" => w.type_names = opt_string(v)?,
        _ => return Ok(false),
    }
    Ok(true)
}

fn apply_wmts(w: &mut Wmts, key: &str, v: &Value) -> AppResult<bool> {
    match key {
        "tileGrid" => {
            w.tile_grid = match v {
                Value::Null => None,
                _ => Some(TileGrid::from_value(v, true)?),
            }
        }
        "urls" => w.urls = opt_string_list(v)?,
        "wmtsLayer" => w.wmts_layer = opt_string(v)?,
        "wmtsStyle" => w.wmts_style = opt_string(v)?,
        "projection" => w.projection = opt_string(v)?,
        "matrixSet" => w.matrix_set = opt_string(v)?,
        "requestEncoding" => w.request_encoding = opt_string(v)?,
        "capabilitiesUrl" => w.capabilities_url = opt_string(v)?,
        _ => return Ok(false),
    }
    Ok(true)
}

fn apply_xyz(x: &mut Xyz, key: &str, v: &Value) -> AppResult<bool> {
    match key {
        "center" => x.center = point_from(v)?,
        "extent" => {
            x.extent = match v {
                Value::Null => None,
                _ => Some(Extent::from_value(v)?),
            }
        }
        "resolutions" => x.resolutions = opt_f64_list(v)?,
        "tileSize" => x.tile_size = opt_i32(v)?,
        _ => return Ok(false),
    }
    Ok(true)
}

// ---------------------------------------------------------------- Layer

#[derive(Clone, Debug, Default)]
pub struct Layer {
    pub id: Option<Id>,
    pub name: Option<String>,
    pub description: Option<String>,
    pub source: Option<DataSource>,
    pub appearance: Option<Appearance>,
}

impl Layer {
    pub const FIELDS: &'static [(&'static str, FieldType)] = &[
        ("id", FieldType::Int),
        ("name", FieldType::Str),
        ("description", FieldType::Str),
    ];

    pub fn apply(&mut self, key: &str, v: &Value) -> AppResult<()> {
        match key {
            "id" => self.id = opt_i32(v)?,
            "name" => self.name = opt_string(v)?,
            "description" => self.description = opt_string(v)?,
            // LayerDataSource is abstract: Jackson cannot build it.
            "source" => match v {
                Value::Null => self.source = None,
                _ => return json_err("Cannot construct instance of LayerDataSource (abstract)"),
            },
            "appearance" => {
                self.appearance = match v {
                    Value::Null => None,
                    _ => Some(Appearance::from_value(v)?),
                }
            }
            _ => return unknown_prop("Layer", key),
        }
        Ok(())
    }

    pub fn project(&self, names: &[&str]) -> Layer {
        let mut out = Layer::default();
        for n in names {
            match *n {
                "id" => out.id = self.id,
                "name" => out.name = self.name.clone(),
                "description" => out.description = self.description.clone(),
                _ => {}
            }
        }
        out
    }

    pub fn field(&self, name: &str) -> Option<FieldVal> {
        Some(match name {
            "id" => FieldVal::Int(self.id),
            "name" => FieldVal::Str(self.name.clone()),
            "description" => FieldVal::Str(self.description.clone()),
            _ => return None,
        })
    }

    pub fn to_json(&self) -> Value {
        obj(vec![
            ("id", j(self.id)),
            ("name", j(&self.name)),
            ("description", j(&self.description)),
            ("source", self.source.as_ref().map(|s| s.to_json()).unwrap_or(Value::Null)),
            (
                "appearance",
                self.appearance.as_ref().map(|a| a.to_json()).unwrap_or(Value::Null),
            ),
        ])
    }

    pub fn from_value(v: &Value) -> AppResult<Layer> {
        build(v, Layer::default(), |t, k, val| t.apply(k, val))
    }
}

// ---------------------------------------------------------------- Ent

/// Any entity of the slice, for the generic endpoints.
#[derive(Clone, Debug)]
pub enum Ent {
    User(User),
    Group(UserGroup),
    Role(Role),
    Layer(Layer),
    Source(DataSource),
    Appearance(Appearance),
}

impl Ent {
    pub fn kind(&self) -> Kind {
        match self {
            Ent::User(_) => Kind::User,
            Ent::Group(_) => Kind::Group,
            Ent::Role(_) => Kind::Role,
            Ent::Layer(_) => Kind::Layer,
            Ent::Source(_) => Kind::Source,
            Ent::Appearance(_) => Kind::Appearance,
        }
    }

    pub fn id(&self) -> Option<Id> {
        match self {
            Ent::User(e) => e.id,
            Ent::Group(e) => e.id,
            Ent::Role(e) => e.id,
            Ent::Layer(e) => e.id,
            Ent::Source(e) => e.id,
            Ent::Appearance(e) => e.id,
        }
    }

    pub fn fields(kind: Kind) -> &'static [(&'static str, FieldType)] {
        match kind {
            Kind::User => User::FIELDS,
            Kind::Group => UserGroup::FIELDS,
            Kind::Role => Role::FIELDS,
            Kind::Layer => Layer::FIELDS,
            Kind::Source => DataSource::FIELDS,
            Kind::Appearance => Appearance::FIELDS,
        }
    }

    /// The default-constructed object of a kind, for POST.
    pub fn new_default(kind: Kind) -> AppResult<Ent> {
        Ok(match kind {
            Kind::User => Ent::User(User::new_default()),
            Kind::Group => Ent::Group(UserGroup::new_default()),
            Kind::Role => Ent::Role(Role::default()),
            Kind::Layer => Ent::Layer(Layer::default()),
            Kind::Appearance => Ent::Appearance(Appearance::new_default()),
            Kind::Source => return json_err("LayerDataSource is abstract"),
        })
    }

    pub fn apply(&mut self, key: &str, v: &Value) -> AppResult<()> {
        match self {
            Ent::User(e) => e.apply(key, v),
            Ent::Group(e) => e.apply(key, v),
            Ent::Role(e) => e.apply(key, v),
            Ent::Layer(e) => e.apply(key, v),
            Ent::Source(e) => e.apply(key, v),
            Ent::Appearance(e) => e.apply(key, v),
        }
    }

    pub fn project(&self, names: &[&str]) -> Ent {
        match self {
            Ent::User(e) => Ent::User(e.project(names)),
            Ent::Group(e) => Ent::Group(e.project(names)),
            Ent::Role(e) => {
                let mut out = Role::default();
                for n in names {
                    match *n {
                        "id" => out.id = e.id,
                        "name" => out.name = e.name.clone(),
                        "description" => out.description = e.description.clone(),
                        _ => {}
                    }
                }
                Ent::Role(out)
            }
            Ent::Layer(e) => Ent::Layer(e.project(names)),
            Ent::Source(e) => {
                // Not reached: the original cannot project abstract sources.
                let mut out = e.clone();
                out.name = None;
                Ent::Source(out)
            }
            Ent::Appearance(e) => Ent::Appearance(e.project(names)),
        }
    }

    pub fn field(&self, name: &str) -> Option<FieldVal> {
        match self {
            Ent::User(e) => e.field(name),
            Ent::Group(e) => e.field(name),
            Ent::Role(e) => match name {
                "id" => Some(FieldVal::Int(e.id)),
                "name" => Some(FieldVal::Str(e.name.clone())),
                "description" => Some(FieldVal::Str(e.description.clone())),
                _ => None,
            },
            Ent::Layer(e) => e.field(name),
            Ent::Source(e) => e.field(name),
            Ent::Appearance(e) => e.field(name),
        }
    }

    pub fn to_json(&self) -> Value {
        match self {
            Ent::User(e) => e.to_json(),
            Ent::Group(e) => e.to_json(),
            Ent::Role(e) => e.to_json(),
            Ent::Layer(e) => e.to_json(),
            Ent::Source(e) => e.to_json(),
            Ent::Appearance(e) => e.to_json(),
        }
    }

    pub fn set_id(&mut self, id: Id) {
        match self {
            Ent::User(e) => e.id = Some(id),
            Ent::Group(e) => e.id = Some(id),
            Ent::Role(e) => e.id = Some(id),
            Ent::Layer(e) => e.id = Some(id),
            Ent::Source(e) => e.id = Some(id),
            Ent::Appearance(e) => e.id = Some(id),
        }
    }
}

/// Keys Jackson ignores on every entity (`@JsonIgnore` on the base class).
pub fn is_ignored_key(key: &str) -> bool {
    matches!(key, "created" | "modified" | "userPermissions" | "groupPermissions")
}

/// Applies a JSON object to a default object in key order, the way
/// Jackson's bean deserialiser does.
pub fn build<T>(
    v: &Value,
    mut t: T,
    apply: impl Fn(&mut T, &str, &Value) -> AppResult<()>,
) -> AppResult<T> {
    match v {
        Value::Object(o) => {
            for (k, val) in o {
                if is_ignored_key(k) {
                    continue;
                }
                apply(&mut t, k, val)?;
            }
            Ok(t)
        }
        _ => json_err("expected a JSON object"),
    }
}

pub fn unknown_prop<T>(ty: &str, key: &str) -> AppResult<T> {
    json_err(format!("Unrecognized field \"{key}\" (class {ty})"))
}

// ---------------------------------------------------------------- JSON helpers

pub fn j<T: serde::Serialize>(t: T) -> Value {
    serde_json::to_value(t).unwrap_or(Value::Null)
}

pub fn obj(pairs: Vec<(&str, Value)>) -> Value {
    Value::Object(obj_map(pairs))
}

pub fn obj_map(pairs: Vec<(&str, Value)>) -> Map<String, Value> {
    let mut m = Map::new();
    for (k, v) in pairs {
        m.insert(k.to_string(), v);
    }
    m
}

pub fn roles_json(roles: &Option<Vec<Role>>) -> Value {
    match roles {
        None => Value::Null,
        Some(rs) => Value::Array(rs.iter().map(|r| r.to_json()).collect()),
    }
}

pub fn f64_list_json(list: &Option<Vec<f64>>) -> Value {
    match list {
        None => Value::Null,
        Some(vs) => Value::Array(
            vs.iter()
                .map(|d| serde_json::Number::from_f64(*d).map(Value::Number).unwrap_or(Value::Null))
                .collect(),
        ),
    }
}

