//! A consistent, in-memory copy of the slice's rows, read in one transaction.
//!
//! The original works on a Hibernate session: eager associations are loaded
//! with their entities, and permission checks look at the loaded maps. A
//! snapshot gives the same view, and it keeps the filter, projection and
//! permission logic simple.

use std::collections::{BTreeMap, HashMap, HashSet};

use sqlx::{PgConnection, Row};

use crate::err::AppResult;
use crate::jsonx::prop_from_db;
use crate::model::*;

#[derive(Default)]
pub struct Snap {
    pub users: BTreeMap<Id, User>,
    pub groups: BTreeMap<Id, UserGroup>,
    pub roles: BTreeMap<Id, Role>,
    pub layers: BTreeMap<Id, Layer>,
    pub sources: BTreeMap<Id, DataSource>,
    pub appearances: BTreeMap<Id, Appearance>,
    /// (user id, group id) pairs of `user_usergroup`.
    pub memberships: HashSet<(Id, Id)>,
    /// entity id -> (user id, permissions) from `userpermissions`.
    pub user_perms: HashMap<Id, Vec<(Id, Vec<String>)>>,
    /// entity id -> (group id, permissions) from `grouppermissions`.
    pub group_perms: HashMap<Id, Vec<(Id, Vec<String>)>>,
}

impl Snap {
    pub async fn load(c: &mut PgConnection) -> AppResult<Snap> {
        let mut s = Snap::default();

        // ---- roles
        for r in sqlx::query("SELECT id, name, description FROM roles ORDER BY id")
            .fetch_all(&mut *c)
            .await?
        {
            let id: Id = r.get("id");
            s.roles.insert(
                id,
                Role {
                    id: Some(id),
                    name: r.get("name"),
                    description: r.get("description"),
                },
            );
        }

        // ---- users (with role ids and group ids)
        let mut user_roles: HashMap<Id, Vec<Id>> = HashMap::new();
        for r in sqlx::query("SELECT user_id, role_id FROM users_roles ORDER BY user_id, role_id")
            .fetch_all(&mut *c)
            .await?
        {
            user_roles.entry(r.get("user_id")).or_default().push(r.get("role_id"));
        }
        for r in sqlx::query("SELECT user_id, usergroup_id FROM user_usergroup")
            .fetch_all(&mut *c)
            .await?
        {
            let (u, g): (Id, Id) = (r.get("user_id"), r.get("usergroup_id"));
            s.memberships.insert((u, g));
        }
        let mut user_groups: BTreeMap<Id, Vec<Id>> = BTreeMap::new();
        for (u, g) in &s.memberships {
            user_groups.entry(*u).or_default().push(*g);
        }
        for v in user_groups.values_mut() {
            v.sort();
        }
        for r in sqlx::query(
            "SELECT u.id, u.accountname, u.active, u.password, p.firstname, p.lastname, \
             p.email, p.birthday, p.language FROM users u JOIN persons p ON p.id = u.id ORDER BY u.id",
        )
        .fetch_all(&mut *c)
        .await?
        {
            let id: Id = r.get("id");
            let role_ids = user_roles.get(&id).cloned().unwrap_or_default();
            let roles: Vec<Role> = role_ids.iter().filter_map(|rid| s.roles.get(rid).cloned()).collect();
            let groups: Vec<GroupRef> = user_groups
                .get(&id)
                .map(|gs| {
                    gs.iter()
                        .map(|g| GroupRef { id: Some(*g), resolve: false })
                        .collect()
                })
                .unwrap_or_default();
            s.users.insert(
                id,
                User {
                    id: Some(id),
                    first_name: r.get("firstname"),
                    last_name: r.get("lastname"),
                    email: r.get("email"),
                    birthday: r.get("birthday"),
                    language: r.get("language"),
                    account_name: r.get("accountname"),
                    password: r.get("password"),
                    active: r.get::<Option<bool>, _>("active").unwrap_or(false),
                    roles: Some(roles),
                    user_groups: Some(groups),
                },
            );
        }

        // ---- groups (members, roles, owner)
        let mut group_roles: HashMap<Id, Vec<Id>> = HashMap::new();
        for r in sqlx::query("SELECT usergroup_id, role_id FROM usergroups_roles ORDER BY usergroup_id, role_id")
            .fetch_all(&mut *c)
            .await?
        {
            group_roles.entry(r.get("usergroup_id")).or_default().push(r.get("role_id"));
        }
        for r in sqlx::query("SELECT id, name, owner_id FROM usergroups ORDER BY id")
            .fetch_all(&mut *c)
            .await?
        {
            let id: Id = r.get("id");
            let owner_id: Option<Id> = r.get("owner_id");
            let members: Vec<User> = s
                .memberships
                .iter()
                .filter(|(_, g)| *g == id)
                .filter_map(|(u, _)| s.users.get(u).cloned())
                .collect();
            let mut members = members;
            members.sort_by_key(|u| u.id);
            let roles: Vec<Role> = group_roles
                .get(&id)
                .map(|rs| rs.iter().filter_map(|rid| s.roles.get(rid).cloned()).collect())
                .unwrap_or_default();
            s.groups.insert(
                id,
                UserGroup {
                    id: Some(id),
                    name: r.get("name"),
                    owner: owner_id.and_then(|o| s.users.get(&o).cloned()),
                    members: Some(members),
                    roles: Some(roles),
                },
            );
        }

        // ---- extents and tile grids
        let mut extents: HashMap<Id, Extent> = HashMap::new();
        for r in sqlx::query(
            "SELECT id, lowerleft_x, lowerleft_y, upperright_x, upperright_y FROM extents",
        )
        .fetch_all(&mut *c)
        .await?
        {
            let id: Id = r.get("id");
            extents.insert(
                id,
                Extent {
                    id: Some(id),
                    lower_left: point_opt(r.get("lowerleft_x"), r.get("lowerleft_y")),
                    upper_right: point_opt(r.get("upperright_x"), r.get("upperright_y")),
                },
            );
        }
        let mut tg_res: HashMap<Id, Vec<f64>> = HashMap::new();
        for r in sqlx::query(
            "SELECT tilegrid_id, resolution FROM tilegrid_resolution ORDER BY tilegrid_id, idx",
        )
        .fetch_all(&mut *c)
        .await?
        {
            let v: Option<f64> = r.get("resolution");
            tg_res.entry(r.get("tilegrid_id")).or_default().push(v.unwrap_or(0.0));
        }
        let mut wmts_ids: HashSet<Id> = HashSet::new();
        for r in sqlx::query("SELECT id FROM wmtstilegrids").fetch_all(&mut *c).await? {
            wmts_ids.insert(r.get("id"));
        }
        let mut matrix: HashMap<Id, Vec<String>> = HashMap::new();
        for r in sqlx::query("SELECT wmtstilegrids_id, matrixids FROM wmtstilegrids_matrixids ORDER BY wmtstilegrids_id")
            .fetch_all(&mut *c)
            .await?
        {
            let v: Option<String> = r.get("matrixids");
            matrix.entry(r.get("wmtstilegrids_id")).or_default().push(v.unwrap_or_default());
        }
        let mut tilegrids: HashMap<Id, TileGrid> = HashMap::new();
        for r in sqlx::query(
            "SELECT id, type, tilegridorigin_x, tilegridorigin_y, tilesize, tilegridextent_id FROM tilegrids",
        )
        .fetch_all(&mut *c)
        .await?
        {
            let id: Id = r.get("id");
            let wmts = wmts_ids.contains(&id);
            let extent_id: Option<Id> = r.get("tilegridextent_id");
            tilegrids.insert(
                id,
                TileGrid {
                    id: Some(id),
                    type_: r.get("type"),
                    origin: point_opt(r.get("tilegridorigin_x"), r.get("tilegridorigin_y")),
                    extent: extent_id.and_then(|e| extents.get(&e).cloned()),
                    tile_size: r.get("tilesize"),
                    resolutions: Some(tg_res.get(&id).cloned().unwrap_or_default()),
                    wmts,
                    matrix_ids: if wmts {
                        Some(matrix.get(&id).cloned().unwrap_or_default())
                    } else {
                        None
                    },
                },
            );
        }

        // ---- layer appearances
        let mut props: HashMap<Id, Vec<(String, PropValue)>> = HashMap::new();
        for r in sqlx::query("SELECT appearance_id, property, value FROM layerappearances_properties ORDER BY appearance_id, property")
            .fetch_all(&mut *c)
            .await?
        {
            let value: Option<String> = r.get("value");
            props
                .entry(r.get("appearance_id"))
                .or_default()
                .push((r.get("property"), prop_from_db(value.as_deref())));
        }
        for r in sqlx::query(
            "SELECT id, attribution, clickable, hovertemplate, hoverable, maxresolution, \
             minresolution, name, opacity, visible FROM layerappearances ORDER BY id",
        )
        .fetch_all(&mut *c)
        .await?
        {
            let id: Id = r.get("id");
            s.appearances.insert(
                id,
                Appearance {
                    id: Some(id),
                    attribution: r.get("attribution"),
                    hoverable: r.get("hoverable"),
                    clickable: r.get("clickable"),
                    hover_template: r.get("hovertemplate"),
                    properties: Some(props.remove(&id).unwrap_or_default()),
                    name: r.get("name"),
                    max_resolution: r.get("maxresolution"),
                    min_resolution: r.get("minresolution"),
                    opacity: r.get("opacity"),
                    visible: r.get("visible"),
                },
            );
        }

        // ---- data sources
        s.sources = load_sources(c, &tilegrids, &extents, &tg_res_unused()).await?;

        // ---- layers
        for r in sqlx::query("SELECT id, name, description, source_id, appearance_id FROM layers ORDER BY id")
            .fetch_all(&mut *c)
            .await?
        {
            let id: Id = r.get("id");
            let source_id: Option<Id> = r.get("source_id");
            let appearance_id: Option<Id> = r.get("appearance_id");
            s.layers.insert(
                id,
                Layer {
                    id: Some(id),
                    name: r.get("name"),
                    description: r.get("description"),
                    source: source_id.and_then(|sid| s.sources.get(&sid).cloned()),
                    appearance: appearance_id.and_then(|aid| s.appearances.get(&aid).cloned()),
                },
            );
        }

        // ---- permissions
        s.user_perms = load_perms(c, "userpermissions", "userpermissions_key").await?;
        s.group_perms = load_perms(c, "grouppermissions", "grouppermissions_key").await?;

        Ok(s)
    }

    /// All entities of a kind, in id order.
    pub fn all(&self, kind: Kind) -> Vec<Ent> {
        match kind {
            Kind::User => self.users.values().cloned().map(Ent::User).collect(),
            Kind::Group => self.groups.values().cloned().map(Ent::Group).collect(),
            Kind::Role => self.roles.values().cloned().map(Ent::Role).collect(),
            Kind::Layer => self.layers.values().cloned().map(Ent::Layer).collect(),
            Kind::Source => self.sources.values().cloned().map(Ent::Source).collect(),
            Kind::Appearance => self.appearances.values().cloned().map(Ent::Appearance).collect(),
        }
    }

    pub fn get(&self, kind: Kind, id: Id) -> Option<Ent> {
        match kind {
            Kind::User => self.users.get(&id).cloned().map(Ent::User),
            Kind::Group => self.groups.get(&id).cloned().map(Ent::Group),
            Kind::Role => self.roles.get(&id).cloned().map(Ent::Role),
            Kind::Layer => self.layers.get(&id).cloned().map(Ent::Layer),
            Kind::Source => self.sources.get(&id).cloned().map(Ent::Source),
            Kind::Appearance => self.appearances.get(&id).cloned().map(Ent::Appearance),
        }
    }
}

fn tg_res_unused() {}

fn point_opt(x: Option<f64>, y: Option<f64>) -> Option<Point> {
    match (x, y) {
        (None, None) => None,
        (x, y) => Some(Point {
            x: x.unwrap_or(0.0),
            y: y.unwrap_or(0.0),
        }),
    }
}

async fn load_sources(
    c: &mut PgConnection,
    tilegrids: &HashMap<Id, TileGrid>,
    extents: &HashMap<Id, Extent>,
    _unused: &(),
) -> AppResult<BTreeMap<Id, DataSource>> {
    let mut base: BTreeMap<Id, DataSource> = BTreeMap::new();
    for r in sqlx::query("SELECT id, name, type, url, format FROM layerdatasources ORDER BY id")
        .fetch_all(&mut *c)
        .await?
    {
        let id: Id = r.get("id");
        base.insert(
            id,
            DataSource {
                id: Some(id),
                name: r.get("name"),
                type_: r.get("type"),
                url: r.get("url"),
                format: r.get("format"),
                kind: SourceKind::Wfs(Wfs::default()), // replaced below
            },
        );
    }

    let mut images: HashMap<Id, ImageWms> = HashMap::new();
    for r in sqlx::query(
        "SELECT id, customrequestpath, height, layernames, layerstyles, requestablebypath, version, width \
         FROM imagewmslayerdatasources",
    )
    .fetch_all(&mut *c)
    .await?
    {
        let id: Id = r.get("id");
        images.insert(
            id,
            ImageWms {
                width: r.get("width"),
                height: r.get("height"),
                version: r.get("version"),
                layer_names: r.get("layernames"),
                layer_styles: r.get("layerstyles"),
                requestable_by_path: r.get("requestablebypath"),
                custom_request_path: r.get("customrequestpath"),
            },
        );
    }
    let mut tile_wms: HashMap<Id, (Option<Id>, Option<bool>)> = HashMap::new();
    for r in sqlx::query("SELECT id, request_with_tiled, tilegrid_id FROM tilewmslayerdatasources")
        .fetch_all(&mut *c)
        .await?
    {
        tile_wms.insert(
            r.get("id"),
            (r.get("tilegrid_id"), r.get("request_with_tiled")),
        );
    }
    let mut wfs: HashMap<Id, Wfs> = HashMap::new();
    for r in sqlx::query("SELECT id, typename, typenames, version FROM wfslayerdatasources")
        .fetch_all(&mut *c)
        .await?
    {
        wfs.insert(
            r.get("id"),
            Wfs {
                version: r.get("version"),
                type_name: r.get("typename"),
                type_names: r.get("typenames"),
            },
        );
    }
    let mut urls: HashMap<Id, Vec<String>> = HashMap::new();
    for r in sqlx::query("SELECT wmtslayerdatasources_id, urls FROM wmtslayerdatasources_urls")
        .fetch_all(&mut *c)
        .await?
    {
        let v: Option<String> = r.get("urls");
        urls.entry(r.get("wmtslayerdatasources_id"))
            .or_default()
            .push(v.unwrap_or_default());
    }
    let mut wmts: HashMap<Id, Wmts> = HashMap::new();
    for r in sqlx::query(
        "SELECT id, capabilitiesurl, matrixset, projection, requestencoding, wmtslayer, wmtsstyle, tilegrid_id \
         FROM wmtslayerdatasources",
    )
    .fetch_all(&mut *c)
    .await?
    {
        let id: Id = r.get("id");
        let tg: Option<Id> = r.get("tilegrid_id");
        wmts.insert(
            id,
            Wmts {
                tile_grid: tg.and_then(|t| tilegrids.get(&t).cloned()),
                urls: Some(urls.remove(&id).unwrap_or_default()),
                wmts_layer: r.get("wmtslayer"),
                wmts_style: r.get("wmtsstyle"),
                projection: r.get("projection"),
                matrix_set: r.get("matrixset"),
                request_encoding: r.get("requestencoding"),
                capabilities_url: r.get("capabilitiesurl"),
            },
        );
    }
    let mut res: HashMap<Id, Vec<f64>> = HashMap::new();
    for r in sqlx::query(
        "SELECT xyzlayerdatasrc_id, resolution FROM xyzlayerdatasrc_resolution ORDER BY xyzlayerdatasrc_id, idx",
    )
    .fetch_all(&mut *c)
    .await?
    {
        let bytes: Option<Vec<u8>> = r.get("resolution");
        res.entry(r.get("xyzlayerdatasrc_id"))
            .or_default()
            .push(crate::javaser::decode_double(bytes.as_deref()));
    }
    let mut xyz: HashMap<Id, Xyz> = HashMap::new();
    for r in sqlx::query("SELECT id, center_x, center_y, tilesize, extent_id FROM xyzlayerdatasources")
        .fetch_all(&mut *c)
        .await?
    {
        let id: Id = r.get("id");
        let ext: Option<Id> = r.get("extent_id");
        xyz.insert(
            id,
            Xyz {
                center: point_opt(r.get("center_x"), r.get("center_y")),
                extent: ext.and_then(|e| extents.get(&e).cloned()),
                resolutions: Some(res.remove(&id).unwrap_or_default()),
                tile_size: r.get("tilesize"),
            },
        );
    }

    let mut out = BTreeMap::new();
    for (id, mut ds) in base {
        let kind = if let Some((tg, rwt)) = tile_wms.get(&id) {
            let image = images.get(&id).cloned().unwrap_or_default();
            Some(SourceKind::TileWms(TileWms {
                image,
                tile_grid: tg.and_then(|t| tilegrids.get(&t).cloned()),
                request_with_tiled: *rwt,
            }))
        } else if let Some(i) = images.get(&id) {
            Some(SourceKind::ImageWms(i.clone()))
        } else if let Some(w) = wfs.get(&id) {
            Some(SourceKind::Wfs(w.clone()))
        } else if let Some(w) = wmts.remove(&id) {
            Some(SourceKind::Wmts(w))
        } else if let Some(x) = xyz.remove(&id) {
            Some(SourceKind::Xyz(x))
        } else {
            None
        };
        if let Some(k) = kind {
            ds.kind = k;
            out.insert(id, ds);
        }
    }
    Ok(out)
}

async fn load_perms(
    c: &mut PgConnection,
    table: &str,
    key_col: &str,
) -> AppResult<HashMap<Id, Vec<(Id, Vec<String>)>>> {
    let sql = format!(
        "SELECT t.entity_id, t.{key_col} AS holder, pp.permissions \
         FROM {table} t LEFT JOIN permissioncollections_permissions pp \
         ON pp.permissioncollections_id = t.{table}_id ORDER BY t.entity_id, t.{key_col}"
    );
    let mut out: HashMap<Id, Vec<(Id, Vec<String>)>> = HashMap::new();
    for r in sqlx::query(&sql).fetch_all(&mut *c).await? {
        let entity: Id = r.get("entity_id");
        let holder: Id = r.get("holder");
        let perm: Option<String> = r.get("permissions");
        let list = out.entry(entity).or_default();
        let idx = match list.iter().position(|(h, _)| *h == holder) {
            Some(i) => i,
            None => {
                list.push((holder, vec![]));
                list.len() - 1
            }
        };
        if let Some(p) = perm {
            list[idx].1.push(p);
        }
    }
    Ok(out)
}

tool_use_result.content:
//! A consistent, in-memory copy of the slice's rows, read in one transaction.
//!
//! The original works on a Hibernate session: eager associations are loaded
//! with their entities, and permission checks look at the loaded maps. A
//! snapshot gives the same view, and it keeps the filter, projection and
//! permission logic simple.

use std::collections::{BTreeMap, HashMap, HashSet};

use sqlx::{PgConnection, Row};

use crate::err::AppResult;
use crate::jsonx::prop_from_db;
use crate::model::*;

#[derive(Default)]
pub struct Snap {
    pub users: BTreeMap<Id, User>,
    pub groups: BTreeMap<Id, UserGroup>,
    pub roles: BTreeMap<Id, Role>,
    pub layers: BTreeMap<Id, Layer>,
    pub sources: BTreeMap<Id, DataSource>,
    pub appearances: BTreeMap<Id, Appearance>,
    /// (user id, group id) pairs of `user_usergroup`.
    pub memberships: HashSet<(Id, Id)>,
    /// entity id -> (user id, permissions) from `userpermissions`.
    pub user_perms: HashMap<Id, Vec<(Id, Vec<String>)>>,
    /// entity id -> (group id, permissions) from `grouppermissions`.
    pub group_perms: HashMap<Id, Vec<(Id, Vec<String>)>>,
}

impl Snap {
    pub async fn load(c: &mut PgConnection) -> AppResult<Snap> {
        let mut s = Snap::default();

        // ---- roles
        for r in sqlx::query("SELECT id, name, description FROM roles ORDER BY id")
            .fetch_all(&mut *c)
            .await?
        {
            let id: Id = r.get("id");
            s.roles.insert(
                id,
                Role {
                    id: Some(id),
                    name: r.get("name"),
                    description: r.get("description"),
                },
            );
        }

        // ---- users (with role ids and group ids)
        let mut user_roles: HashMap<Id, Vec<Id>> = HashMap::new();
        for r in sqlx::query("SELECT user_id, role_id FROM users_roles ORDER BY user_id, role_id")
            .fetch_all(&mut *c)
            .await?
        {
            user_roles.entry(r.get("user_id")).or_default().push(r.get("role_id"));
        }
        for r in sqlx::query("SELECT user_id, usergroup_id FROM user_usergroup")
            .fetch_all(&mut *c)
            .await?
        {
            let (u, g): (Id, Id) = (r.get("user_id"), r.get("usergroup_id"));
            s.memberships.insert((u, g));
        }
        let mut user_groups: BTreeMap<Id, Vec<Id>> = BTreeMap::new();
        for (u, g) in &s.memberships {
            user_groups.entry(*u).or_default().push(*g);
        }
        for v in user_groups.values_mut() {
            v.sort();
        }
        for r in sqlx::query(
            "SELECT u.id, u.accountname, u.active, u.password, p.firstname, p.lastname, \
             p.email, p.birthday, p.language FROM users u JOIN persons p ON p.id = u.id ORDER BY u.id",
        )
        .fetch_all(&mut *c)
        .await?
        {
            let id: Id = r.get("id");
            let role_ids = user_roles.get(&id).cloned().unwrap_or_default();
            let roles: Vec<Role> = role_ids.iter().filter_map(|rid| s.roles.get(rid).cloned()).collect();
            let groups: Vec<GroupRef> = user_groups
                .get(&id)
                .map(|gs| {
                    gs.iter()
                        .map(|g| GroupRef { id: Some(*g), resolve: false })
                        .collect()
                })
                .unwrap_or_default();
            s.users.insert(
                id,
                User {
                    id: Some(id),
                    first_name: r.get("firstname"),
                    last_name: r.get("lastname"),
                    email: r.get("email"),
                    birthday: r.get("birthday"),
                    language: r.get("language"),
                    account_name: r.get("accountname"),
                    password: r.get("password"),
                    active: r.get::<Option<bool>, _>("active").unwrap_or(false),
                    roles: Some(roles),
                    user_groups: Some(groups),
                },
            );
        }

        // ---- groups (members, roles, owner)
        let mut group_roles: HashMap<Id, Vec<Id>> = HashMap::new();
        for r in sqlx::query("SELECT usergroup_id, role_id FROM usergroups_roles ORDER BY usergroup_id, role_id")
            .fetch_all(&mut *c)
            .await?
        {
            group_roles.entry(r.get("usergroup_id")).or_default().push(r.get("role_id"));
        }
        for r in sqlx::query("SELECT id, name, owner_id FROM usergroups ORDER BY id")
            .fetch_all(&mut *c)
            .await?
        {
            let id: Id = r.get("id");
            let owner_id: Option<Id> = r.get("owner_id");
            let members: Vec<User> = s
                .memberships
                .iter()
                .filter(|(_, g)| *g == id)
                .filter_map(|(u, _)| s.users.get(u).cloned())
                .collect();
            let mut members = members;
            members.sort_by_key(|u| u.id);
            let roles: Vec<Role> = group_roles
                .get(&id)
                .map(|rs| rs.iter().filter_map(|rid| s.roles.get(rid).cloned()).collect())
                .unwrap_or_default();
            s.groups.insert(
                id,
                UserGroup {
                    id: Some(id),
                    name: r.get("name"),
                    owner: owner_id.and_then(|o| s.users.get(&o).cloned()),
                    members: Some(members),
                    roles: Some(roles),
                },
            );
        }

        // ---- extents and tile grids
        let mut extents: HashMap<Id, Extent> = HashMap::new();
        for r in sqlx::query(
            "SELECT id, lowerleft_x, lowerleft_y, upperright_x, upperright_y FROM extents",
        )
        .fetch_all(&mut *c)
        .await?
        {
            let id: Id = r.get("id");
            extents.insert(
                id,
                Extent {
                    id: Some(id),
                    lower_left: point_opt(r.get("lowerleft_x"), r.get("lowerleft_y")),
                    upper_right: point_opt(r.get("upperright_x"), r.get("upperright_y")),
                },
            );
        }
        let mut tg_res: HashMap<Id, Vec<f64>> = HashMap::new();
        for r in sqlx::query(
            "SELECT tilegrid_id, resolution FROM tilegrid_resolution ORDER BY tilegrid_id, idx",
        )
        .fetch_all(&mut *c)
        .await?
        {
            let v: Option<f64> = r.get("resolution");
            tg_res.entry(r.get("tilegrid_id")).or_default().push(v.unwrap_or(0.0));
        }
        let mut wmts_ids: HashSet<Id> = HashSet::new();
        for r in sqlx::query("SELECT id FROM wmtstilegrids").fetch_all(&mut *c).await? {
            wmts_ids.insert(r.get("id"));
        }
        let mut matrix: HashMap<Id, Vec<String>> = HashMap::new();
        for r in sqlx::query("SELECT wmtstilegrids_id, matrixids FROM wmtstilegrids_matrixids ORDER BY wmtstilegrids_id")
            .fetch_all(&mut *c)
            .await?
        {
            let v: Option<String> = r.get("matrixids");
            matrix.entry(r.get("wmtstilegrids_id")).or_default().push(v.unwrap_or_default());
        }
        let mut tilegrids: HashMap<Id, TileGrid> = HashMap::new();
        for r in sqlx::query(
            "SELECT id, type, tilegridorigin_x, tilegridorigin_y, tilesize, tilegridextent_id FROM tilegrids",
        )
        .fetch_all(&mut *c)
        .await?
        {
            let id: Id = r.get("id");
            let wmts = wmts_ids.contains(&id);
            let extent_id: Option<Id> = r.get("tilegridextent_id");
            tilegrids.insert(
                id,
                TileGrid {
                    id: Some(id),
                    type_: r.get("type"),
                    origin: point_opt(r.get("tilegridorigin_x"), r.get("tilegridorigin_y")),
                    extent: extent_id.and_then(|e| extents.get(&e).cloned()),
                    tile_size: r.get("tilesize"),
                    resolutions: Some(tg_res.get(&id).cloned().unwrap_or_default()),
                    wmts,
                    matrix_ids: if wmts {
                        Some(matrix.get(&id).cloned().unwrap_or_default())
                    } else {
                        None
                    },
                },
            );
        }

        // ---- layer appearances
        let mut props: HashMap<Id, Vec<(String, PropValue)>> = HashMap::new();
        for r in sqlx::query("SELECT appearance_id, property, value FROM layerappearances_properties ORDER BY appearance_id, property")
            .fetch_all(&mut *c)
            .await?
        {
            let value: Option<String> = r.get("value");
            props
                .entry(r.get("appearance_id"))
                .or_default()
                .push((r.get("property"), prop_from_db(value.as_deref())));
        }
        for r in sqlx::query(
            "SELECT id, attribution, clickable, hovertemplate, hoverable, maxresolution, \
             minresolution, name, opacity, visible FROM layerappearances ORDER BY id",
        )
        .fetch_all(&mut *c)
        .await?
        {
            let id: Id = r.get("id");
            s.appearances.insert(
                id,
                Appearance {
                    id: Some(id),
                    attribution: r.get("attribution"),
                    hoverable: r.get("hoverable"),
                    clickable: r.get("clickable"),
                    hover_template: r.get("hovertemplate"),
                    properties: Some(props.remove(&id).unwrap_or_default()),
                    name: r.get("name"),
                    max_resolution: r.get("maxresolution"),
                    min_resolution: r.get("minresolution"),
                    opacity: r.get("opacity"),
                    visible: r.get("visible"),
                },
            );
        }

        // ---- data sources
        s.sources = load_sources(c, &tilegrids, &extents, &tg_res_unused()).await?;

        // ---- layers
        for r in sqlx::query("SELECT id, name, description, source_id, appearance_id FROM layers ORDER BY id")
            .fetch_all(&mut *c)
            .await?
        {
            let id: Id = r.get("id");
            let source_id: Option<Id> = r.get("source_id");
            let appearance_id: Option<Id> = r.get("appearance_id");
            s.layers.insert(
                id,
                Layer {
                    id: Some(id),
                    name: r.get("name"),
                    description: r.get("description"),
                    source: source_id.and_then(|sid| s.sources.get(&sid).cloned()),
                    appearance: appearance_id.and_then(|aid| s.appearances.get(&aid).cloned()),
                },
            );
        }

        // ---- permissions
        s.user_perms = load_perms(c, "userpermissions", "userpermissions_key").await?;
        s.group_perms = load_perms(c, "grouppermissions", "grouppermissions_key").await?;

        Ok(s)
    }

    /// All entities of a kind, in id order.
    pub fn all(&self, kind: Kind) -> Vec<Ent> {
        match kind {
            Kind::User => self.users.values().cloned().map(Ent::User).collect(),
            Kind::Group => self.groups.values().cloned().map(Ent::Group).collect(),
            Kind::Role => self.roles.values().cloned().map(Ent::Role).collect(),
            Kind::Layer => self.layers.values().cloned().map(Ent::Layer).collect(),
            Kind::Source => self.sources.values().cloned().map(Ent::Source).collect(),
            Kind::Appearance => self.appearances.values().cloned().map(Ent::Appearance).collect(),
        }
    }

    pub fn get(&self, kind: Kind, id: Id) -> Option<Ent> {
        match kind {
            Kind::User => self.users.get(&id).cloned().map(Ent::User),
            Kind::Group => self.groups.get(&id).cloned().map(Ent::Group),
            Kind::Role => self.roles.get(&id).cloned().map(Ent::Role),
            Kind::Layer => self.layers.get(&id).cloned().map(Ent::Layer),
            Kind::Source => self.sources.get(&id).cloned().map(Ent::Source),
            Kind::Appearance => self.appearances.get(&id).cloned().map(Ent::Appearance),
        }
    }
}

fn tg_res_unused() {}

fn point_opt(x: Option<f64>, y: Option<f64>) -> Option<Point> {
    match (x, y) {
        (None, None) => None,
        (x, y) => Some(Point {
            x: x.unwrap_or(0.0),
            y: y.unwrap_or(0.0),
        }),
    }
}

async fn load_sources(
    c: &mut PgConnection,
    tilegrids: &HashMap<Id, TileGrid>,
    extents: &HashMap<Id, Extent>,
    _unused: &(),
) -> AppResult<BTreeMap<Id, DataSource>> {
    let mut base: BTreeMap<Id, DataSource> = BTreeMap::new();
    for r in sqlx::query("SELECT id, name, type, url, format FROM layerdatasources ORDER BY id")
        .fetch_all(&mut *c)
        .await?
    {
        let id: Id = r.get("id");
        base.insert(
            id,
            DataSource {
                id: Some(id),
                name: r.get("name"),
                type_: r.get("type"),
                url: r.get("url"),
                format: r.get("format"),
                kind: SourceKind::Wfs(Wfs::default()), // replaced below
            },
        );
    }

    let mut images: HashMap<Id, ImageWms> = HashMap::new();
    for r in sqlx::query(
        "SELECT id, customrequestpath, height, layernames, layerstyles, requestablebypath, version, width \
         FROM imagewmslayerdatasources",
    )
    .fetch_all(&mut *c)
    .await?
    {
        let id: Id = r.get("id");
        images.insert(
            id,
            ImageWms {
                width: r.get("width"),
                height: r.get("height"),
                version: r.get("version"),
                layer_names: r.get("layernames"),
                layer_styles: r.get("layerstyles"),
                requestable_by_path: r.get("requestablebypath"),
                custom_request_path: r.get("customrequestpath"),
            },
        );
    }
    let mut tile_wms: HashMap<Id, (Option<Id>, Option<bool>)> = HashMap::new();
    for r in sqlx::query("SELECT id, request_with_tiled, tilegrid_id FROM tilewmslayerdatasources")
        .fetch_all(&mut *c)
        .await?
    {
        tile_wms.insert(
            r.get("id"),
            (r.get("tilegrid_id"), r.get("request_with_tiled")),
        );
    }
    let mut wfs: HashMap<Id, Wfs> = HashMap::new();
    for r in sqlx::query("SELECT id, typename, typenames, version FROM wfslayerdatasources")
        .fetch_all(&mut *c)
        .await?
    {
        wfs.insert(
            r.get("id"),
            Wfs {
                version: r.get("version"),
                type_name: r.get("typename"),
                type_names: r.get("typenames"),
            },
        );
    }
    let mut urls: HashMap<Id, Vec<String>> = HashMap::new();
    for r in sqlx::query("SELECT wmtslayerdatasources_id, urls FROM wmtslayerdatasources_urls")
        .fetch_all(&mut *c)
        .await?
    {
        let v: Option<String> = r.get("urls");
        urls.entry(r.get("wmtslayerdatasources_id"))
            .or_default()
            .push(v.unwrap_or_default());
    }
    let mut wmts: HashMap<Id, Wmts> = HashMap::new();
    for r in sqlx::query(
        "SELECT id, capabilitiesurl, matrixset, projection, requestencoding, wmtslayer, wmtsstyle, tilegrid_id \
         FROM wmtslayerdatasources",
    )
    .fetch_all(&mut *c)
    .await?
    {
        let id: Id = r.get("id");
        let tg: Option<Id> = r.get("tilegrid_id");
        wmts.insert(
            id,
            Wmts {
                tile_grid: tg.and_then(|t| tilegrids.get(&t).cloned()),
                urls: Some(urls.remove(&id).unwrap_or_default()),
                wmts_layer: r.get("wmtslayer"),
                wmts_style: r.get("wmtsstyle"),
                projection: r.get("projection"),
                matrix_set: r.get("matrixset"),
                request_encoding: r.get("requestencoding"),
                capabilities_url: r.get("capabilitiesurl"),
            },
        );
    }
    let mut res: HashMap<Id, Vec<f64>> = HashMap::new();
    for r in sqlx::query(
        "SELECT xyzlayerdatasrc_id, resolution FROM xyzlayerdatasrc_resolution ORDER BY xyzlayerdatasrc_id, idx",
    )
    .fetch_all(&mut *c)
    .await?
    {
        let bytes: Option<Vec<u8>> = r.get("resolution");
        res.entry(r.get("xyzlayerdatasrc_id"))
            .or_default()
            .push(crate::javaser::decode_double(bytes.as_deref()));
    }
    let mut xyz: HashMap<Id, Xyz> = HashMap::new();
    for r in sqlx::query("SELECT id, center_x, center_y, tilesize, extent_id FROM xyzlayerdatasources")
        .fetch_all(&mut *c)
        .await?
    {
        let id: Id = r.get("id");
        let ext: Option<Id> = r.get("extent_id");
        xyz.insert(
            id,
            Xyz {
                center: point_opt(r.get("center_x"), r.get("center_y")),
                extent: ext.and_then(|e| extents.get(&e).cloned()),
                resolutions: Some(res.remove(&id).unwrap_or_default()),
                tile_size: r.get("tilesize"),
            },
        );
    }

    let mut out = BTreeMap::new();
    for (id, mut ds) in base {
        let kind = if let Some((tg, rwt)) = tile_wms.get(&id) {
            let image = images.get(&id).cloned().unwrap_or_default();
            Some(SourceKind::TileWms(TileWms {
                image,
                tile_grid: tg.and_then(|t| tilegrids.get(&t).cloned()),
                request_with_tiled: *rwt,
            }))
        } else if let Some(i) = images.get(&id) {
            Some(SourceKind::ImageWms(i.clone()))
        } else if let Some(w) = wfs.get(&id) {
            Some(SourceKind::Wfs(w.clone()))
        } else if let Some(w) = wmts.remove(&id) {
            Some(SourceKind::Wmts(w))
        } else if let Some(x) = xyz.remove(&id) {
            Some(SourceKind::Xyz(x))
        } else {
            None
        };
        if let Some(k) = kind {
            ds.kind = k;
            out.insert(id, ds);
        }
    }
    Ok(out)
}

async fn load_perms(
    c: &mut PgConnection,
    table: &str,
    key_col: &str,
) -> AppResult<HashMap<Id, Vec<(Id, Vec<String>)>>> {
    let sql = format!(
        "SELECT t.entity_id, t.{key_col} AS holder, pp.permissions \
         FROM {table} t LEFT JOIN permissioncollections_permissions pp \
         ON pp.permissioncollections_id = t.{table}_id ORDER BY t.entity_id, t.{key_col}"
    );
    let mut out: HashMap<Id, Vec<(Id, Vec<String>)>> = HashMap::new();
    for r in sqlx::query(&sql).fetch_all(&mut *c).await? {
        let entity: Id = r.get("entity_id");
        let holder: Id = r.get("holder");
        let perm: Option<String> = r.get("permissions");
        let list = out.entry(entity).or_default();
        let idx = match list.iter().position(|(h, _)| *h == holder) {
            Some(i) => i,
            None => {
                list.push((holder, vec![]));
                list.len() - 1
            }
        };
        if let Some(p) = perm {
            list[idx].1.push(p);
        }
    }
    Ok(out)
}

tool_use_result.originalFile:
//! A consistent, in-memory copy of the slice's rows, read in one transaction.
//!
//! The original works on a Hibernate session: eager associations are loaded
//! with their entities, and permission checks look at the loaded maps. A
//! snapshot gives the same view, and it keeps the filter, projection and
//! permission logic simple.

use std::collections::{BTreeMap, HashMap, HashSet};

use sqlx::{PgConnection, Row};

use crate::err::AppResult;
use crate::jsonx::prop_from_db;
use crate::model::*;

#[derive(Default)]
pub struct Snap {
    pub users: BTreeMap<Id, User>,
    pub groups: BTreeMap<Id, UserGroup>,
    pub roles: BTreeMap<Id, Role>,
    pub layers: BTreeMap<Id, Layer>,
    pub sources: BTreeMap<Id, DataSource>,
    pub appearances: BTreeMap<Id, Appearance>,
    /// (user id, group id) pairs of `user_usergroup`.
    pub memberships: HashSet<(Id, Id)>,
    /// entity id -> (user id, permissions) from `userpermissions`.
    pub user_perms: HashMap<Id, Vec<(Id, Vec<String>)>>,
    /// entity id -> (group id, permissions) from `grouppermissions`.
    pub group_perms: HashMap<Id, Vec<(Id, Vec<String>)>>,
}

impl Snap {
    pub async fn load(c: &mut PgConnection) -> AppResult<Snap> {
        let mut s = Snap::default();

        // ---- roles
        for r in sqlx::query("SELECT id, name, description FROM roles ORDER BY id")
            .fetch_all(&mut *c)
            .await?
        {
            let id: Id = r.get("id");
            s.roles.insert(
                id,
                Role {
                    id: Some(id),
                    name: r.get("name"),
                    description: r.get("description"),
                },
            );
        }

        // ---- users (with role ids and group ids)
        let mut user_roles: HashMap<Id, Vec<Id>> = HashMap::new();
        for r in sqlx::query("SELECT user_id, role_id FROM users_roles ORDER BY user_id, role_id")
            .fetch_all(&mut *c)
            .await?
        {
            user_roles.entry(r.get("user_id")).or_default().push(r.get("role_id"));
        }
        for r in sqlx::query("SELECT user_id, usergroup_id FROM user_usergroup")
            .fetch_all(&mut *c)
            .await?
        {
            let (u, g): (Id, Id) = (r.get("user_id"), r.get("usergroup_id"));
            s.memberships.insert((u, g));
        }
        let mut user_groups: BTreeMap<Id, Vec<Id>> = BTreeMap::new();
        for (u, g) in &s.memberships {
            user_groups.entry(*u).or_default().push(*g);
        }
        for v in user_groups.values_mut() {
            v.sort();
        }
        for r in sqlx::query(
            "SELECT u.id, u.accountname, u.active, u.password, p.firstname, p.lastname, \
             p.email, p.birthday, p.language FROM users u JOIN persons p ON p.id = u.id ORDER BY u.id",
        )
        .fetch_all(&mut *c)
        .await?
        {
            let id: Id = r.get("id");
            let role_ids = user_roles.get(&id).cloned().unwrap_or_default();
            let roles: Vec<Role> = role_ids.iter().filter_map(|rid| s.roles.get(rid).cloned()).collect();
            let groups: Vec<GroupRef> = user_groups
                .get(&id)
                .map(|gs| {
                    gs.iter()
                        .map(|g| GroupRef { id: Some(*g), resolve: false })
                        .collect()
                })
                .unwrap_or_default();
            s.users.insert(
                id,
                User {
                    id: Some(id),
                    first_name: r.get("firstname"),
                    last_name: r.get("lastname"),
                    email: r.get("email"),
                    birthday: r.get("birthday"),
                    language: r.get("language"),
                    account_name: r.get("accountname"),
                    password: r.get("password"),
                    active: r.get::<Option<bool>, _>("active").unwrap_or(false),
                    roles: Some(roles),
                    user_groups: Some(groups),
                },
            );
        }

        // ---- groups (members, roles, owner)
        let mut group_roles: HashMap<Id, Vec<Id>> = HashMap::new();
        for r in sqlx::query("SELECT usergroup_id, role_id FROM usergroups_roles ORDER BY usergroup_id, role_id")
            .fetch_all(&mut *c)
            .await?
        {
            group_roles.entry(r.get("usergroup_id")).or_default().push(r.get("role_id"));
        }
        for r in sqlx::query("SELECT id, name, owner_id FROM usergroups ORDER BY id")
            .fetch_all(&mut *c)
            .await?
        {
            let id: Id = r.get("id");
            let owner_id: Option<Id> = r.get("owner_id");
            let members: Vec<User> = s
                .memberships
                .iter()
                .filter(|(_, g)| *g == id)
                .filter_map(|(u, _)| s.users.get(u).cloned())
                .collect();
            let mut members = members;
            members.sort_by_key(|u| u.id);
            let roles: Vec<Role> = group_roles
                .get(&id)
                .map(|rs| rs.iter().filter_map(|rid| s.roles.get(rid).cloned()).collect())
                .unwrap_or_default();
            s.groups.insert(
                id,
                UserGroup {
                    id: Some(id),
                    name: r.get("name"),
                    owner: owner_id.and_then(|o| s.users.get(&o).cloned()),
                    members: Some(members),
                    roles: Some(roles),
                },
            );
        }

        // ---- extents and tile grids
        let mut extents: HashMap<Id, Extent> = HashMap::new();
        for r in sqlx::query(
            "SELECT id, lowerleft_x, lowerleft_y, upperright_x, upperright_y FROM extents",
        )
        .fetch_all(&mut *c)
        .await?
        {
            let id: Id = r.get("id");
            extents.insert(
                id,
                Extent {
                    id: Some(id),
                    lower_left: point_opt(r.get("lowerleft_x"), r.get("lowerleft_y")),
                    upper_right: point_opt(r.get("upperright_x"), r.get("upperright_y")),
                },
            );
        }
        let mut tg_res: HashMap<Id, Vec<f64>> = HashMap::new();
        for r in sqlx::query(
            "SELECT tilegrid_id, resolution FROM tilegrid_resolution ORDER BY tilegrid_id, idx",
        )
        .fetch_all(&mut *c)
        .await?
        {
            let v: Option<f64> = r.get("resolution");
            tg_res.entry(r.get("tilegrid_id")).or_default().push(v.unwrap_or(0.0));
        }
        let mut wmts_ids: HashSet<Id> = HashSet::new();
        for r in sqlx::query("SELECT id FROM wmtstilegrids").fetch_all(&mut *c).await? {
            wmts_ids.insert(r.get("id"));
        }
        let mut matrix: HashMap<Id, Vec<String>> = HashMap::new();
        for r in sqlx::query("SELECT wmtstilegrids_id, matrixids FROM wmtstilegrids_matrixids ORDER BY wmtstilegrids_id")
            .fetch_all(&mut *c)
            .await?
        {
            let v: Option<String> = r.get("matrixids");
            matrix.entry(r.get("wmtstilegrids_id")).or_default().push(v.unwrap_or_default());
        }
        let mut tilegrids: HashMap<Id, TileGrid> = HashMap::new();
        for r in sqlx::query(
            "SELECT id, type, tilegridorigin_x, tilegridorigin_y, tilesize, tilegridextent_id FROM tilegrids",
        )
        .fetch_all(&mut *c)
        .await?
        {
            let id: Id = r.get("id");
            let wmts = wmts_ids.contains(&id);
            let extent_id: Option<Id> = r.get("tilegridextent_id");
            tilegrids.insert(
                id,
                TileGrid {
                    id: Some(id),
                    type_: r.get("type"),
                    origin: point_opt(r.get("tilegridorigin_x"), r.get("tilegridorigin_y")),
                    extent: extent_id.and_then(|e| extents.get(&e).cloned()),
                    tile_size: r.get("tilesize"),
                    resolutions: Some(tg_res.get(&id).cloned().unwrap_or_default()),
                    wmts,
                    matrix_ids: if wmts {
                        Some(matrix.get(&id).cloned().unwrap_or_default())
                    } else {
                        None
                    },
                },
            );
        }

        // ---- layer appearances
        let mut props: HashMap<Id, Vec<(String, PropValue)>> = HashMap::new();
        for r in sqlx::query("SELECT appearance_id, property, value FROM layerappearances_properties ORDER BY appearance_id, property")
            .fetch_all(&mut *c)
            .await?
        {
            let value: Option<String> = r.get("value");
            props
                .entry(r.get("appearance_id"))
                .or_default()
                .push((r.get("property"), prop_from_db(value.as_deref())));
        }
        for r in sqlx::query(
            "SELECT id, attribution, clickable, hovertemplate, hoverable, maxresolution, \
             minresolution, name, opacity, visible FROM layerappearances ORDER BY id",
        )
        .fetch_all(&mut *c)
        .await?
        {
            let id: Id = r.get("id");
            s.appearances.insert(
                id,
                Appearance {
                    id: Some(id),
                    attribution: r.get("attribution"),
                    hoverable: r.get("hoverable"),
                    clickable: r.get("clickable"),
                    hover_template: r.get("hovertemplate"),
                    properties: Some(props.remove(&id).unwrap_or_default()),
                    name: r.get("name"),
                    max_resolution: r.get("maxresolution"),
                    min_resolution: r.get("minresolution"),
                    opacity: r.get("opacity"),
                    visible: r.get("visible"),
                },
            );
        }

        // ---- data sources
        s.sources = load_sources(c, &tilegrids, &extents, &tg_res_unused()).await?;

        // ---- layers
        for r in sqlx::query("SELECT id, name, description, source_id, appearance_id FROM layers ORDER BY id")
            .fetch_all(&mut *c)
            .await?
        {
            let id: Id = r.get("id");
            let source_id: Option<Id> = r.get("source_id");
            let appearance_id: Option<Id> = r.get("appearance_id");
            s.layers.insert(
                id,
                Layer {
                    id: Some(id),
                    name: r.get("name"),
                    description: r.get("description"),
                    source: source_id.and_then(|sid| s.sources.get(&sid).cloned()),
                    appearance: appearance_id.and_then(|aid| s.appearances.get(&aid).cloned()),
                },
            );
        }

        // ---- permissions
        s.user_perms = load_perms(c, "userpermissions", "userpermissions_key").await?;
        s.group_perms = load_perms(c, "grouppermissions", "grouppermissions_key").await?;

        Ok(s)
    }

    /// All entities of a kind, in id order.
    pub fn all(&self, kind: Kind) -> Vec<Ent> {
        match kind {
            Kind::User => self.users.values().cloned().map(Ent::User).collect(),
            Kind::Group => self.groups.values().cloned().map(Ent::Group).collect(),
            Kind::Role => self.roles.values().cloned().map(Ent::Role).collect(),
            Kind::Layer => self.layers.values().cloned().map(Ent::Layer).collect(),
            Kind::Source => self.sources.values().cloned().map(Ent::Source).collect(),
            Kind::Appearance => self.appearances.values().cloned().map(Ent::Appearance).collect(),
        }
    }

    pub fn get(&self, kind: Kind, id: Id) -> Option<Ent> {
        match kind {
            Kind::User => self.users.get(&id).cloned().map(Ent::User),
            Kind::Group => self.groups.get(&id).cloned().map(Ent::Group),
            Kind::Role => self.roles.get(&id).cloned().map(Ent::Role),
            Kind::Layer => self.layers.get(&id).cloned().map(Ent::Layer),
            Kind::Source => self.sources.get(&id).cloned().map(Ent::Source),
            Kind::Appearance => self.appearances.get(&id).cloned().map(Ent::Appearance),
        }
    }
}

fn tg_res_unused() {}

fn point_opt(x: Option<f64>, y: Option<f64>) -> Option<Point> {
    match (x, y) {
        (None, None) => None,
        (x, y) => Some(Point {
            x: x.unwrap_or(0.0),
            y: y.unwrap_or(0.0),
        }),
    }
}

async fn load_sources(
    c: &mut PgConnection,
    tilegrids: &HashMap<Id, TileGrid>,
    extents: &HashMap<Id, Extent>,
    _unused: &(),
) -> AppResult<BTreeMap<Id, DataSource>> {
    let mut base: BTreeMap<Id, DataSource> = BTreeMap::new();
    for r in sqlx::query("SELECT id, name, type, url, format FROM layerdatasources ORDER BY id")
        .fetch_all(&mut *c)
        .await?
    {
        let id: Id = r.get("id");
        base.insert(
            id,
            DataSource {
                id: Some(id),
                name: r.get("name"),
                type_: r.get("type"),
                url: r.get("url"),
                format: r.get("format"),
                kind: SourceKind::Wfs(Wfs::default()), // replaced below
            },
        );
    }

    let mut images: HashMap<Id, ImageWms> = HashMap::new();
    for r in sqlx::query(
        "SELECT id, customrequestpath, height, layernames, layerstyles, requestablebypath, version, width \
         FROM imagewmslayerdatasources",
    )
    .fetch_all(&mut *c)
    .await?
    {
        let id: Id = r.get("id");
        images.insert(
            id,
            ImageWms {
                width: r.get("width"),
                height: r.get("height"),
                version: r.get("version"),
                layer_names: r.get("layernames"),
                layer_styles: r.get("layerstyles"),
                requestable_by_path: r.get("requestablebypath"),
                custom_request_path: r.get("customrequestpath"),
            },
        );
    }
    let mut tile_wms: HashMap<Id, (Option<Id>, Option<bool>)> = HashMap::new();
    for r in sqlx::query("SELECT id, request_with_tiled, tilegrid_id FROM tilewmslayerdatasources")
        .fetch_all(&mut *c)
        .await?
    {
        tile_wms.insert(
            r.get("id"),
            (r.get("tilegrid_id"), r.get("request_with_tiled")),
        );
    }
    let mut wfs: HashMap<Id, Wfs> = HashMap::new();
    for r in sqlx::query("SELECT id, typename, typenames, version FROM wfslayerdatasources")
        .fetch_all(&mut *c)
        .await?
    {
        wfs.insert(
            r.get("id"),
            Wfs {
                version: r.get("version"),
                type_name: r.get("typename"),
                type_names: r.get("typenames"),
            },
        );
    }
    let mut urls: HashMap<Id, Vec<String>> = HashMap::new();
    for r in sqlx::query("SELECT wmtslayerdatasources_id, urls FROM wmtslayerdatasources_urls")
        .fetch_all(&mut *c)
        .await?
    {
        let v: Option<String> = r.get("urls");
        urls.entry(r.get("wmtslayerdatasources_id"))
            .or_default()
            .push(v.unwrap_or_default());
    }
    let mut wmts: HashMap<Id, Wmts> = HashMap::new();
    for r in sqlx::query(
        "SELECT id, capabilitiesurl, matrixset, projection, requestencoding, wmtslayer, wmtsstyle, tilegrid_id \
         FROM wmtslayerdatasources",
    )
    .fetch_all(&mut *c)
    .await?
    {
        let id: Id = r.get("id");
        let tg: Option<Id> = r.get("tilegrid_id");
        wmts.insert(
            id,
            Wmts {
                tile_grid: tg.and_then(|t| tilegrids.get(&t).cloned()),
                urls: Some(urls.remove(&id).unwrap_or_default()),
                wmts_layer: r.get("wmtslayer"),
                wmts_style: r.get("wmtsstyle"),
                projection: r.get("projection"),
                matrix_set: r.get("matrixset"),
                request_encoding: r.get("requestencoding"),
                capabilities_url: r.get("capabilitiesurl"),
            },
        );
    }
    let mut res: HashMap<Id, Vec<f64>> = HashMap::new();
    for r in sqlx::query(
        "SELECT xyzlayerdatasrc_id, resolution FROM xyzlayerdatasrc_resolution ORDER BY xyzlayerdatasrc_id, idx",
    )
    .fetch_all(&mut *c)
    .await?
    {
        let bytes: Option<Vec<u8>> = r.get("resolution");
        res.entry(r.get("xyzlayerdatasrc_id"))
            .or_default()
            .push(crate::javaser::decode_double(bytes.as_deref()));
    }
    let mut xyz: HashMap<Id, Xyz> = HashMap::new();
    for r in sqlx::query("SELECT id, center_x, center_y, tilesize, extent_id FROM xyzlayerdatasources")
        .fetch_all(&mut *c)
        .await?
    {
        let id: Id = r.get("id");
        let ext: Option<Id> = r.get("extent_id");
        xyz.insert(
            id,
            Xyz {
                center: point_opt(r.get("center_x"), r.get("center_y")),
                extent: ext.and_then(|e| extents.get(&e).cloned()),
                resolutions: Some(res.remove(&id).unwrap_or_default()),
                tile_size: r.get("tilesize"),
            },
        );
    }

    let mut out = BTreeMap::new();
    for (id, mut ds) in base {
        let kind = if let Some((tg, rwt)) = tile_wms.get(&id) {
            let image = images.get(&id).cloned().unwrap_or_default();
            Some(SourceKind::TileWms(TileWms {
                image,
                tile_grid: tg.and_then(|t| tilegrids.get(&t).cloned()),
                request_with_tiled: *rwt,
            }))
        } else if let Some(i) = images.get(&id) {
            Some(SourceKind::ImageWms(i.clone()))
        } else if let Some(w) = wfs.get(&id) {
            Some(SourceKind::Wfs(w.clone()))
        } else if let Some(w) = wmts.remove(&id) {
            Some(SourceKind::Wmts(w))
        } else if let Some(x) = xyz.remove(&id) {
            Some(SourceKind::Xyz(x))
        } else {
            None
        };
        if let Some(k) = kind {
            ds.kind = k;
            out.insert(id, ds);
        }
    }
    Ok(out)
}

async fn load_perms(
    c: &mut PgConnection,
    table: &str,
    key_col: &str,
) -> AppResult<HashMap<Id, Vec<(Id, Vec<String>)>>> {
    let sql = format!(
        "SELECT t.entity_id, t.{key_col} AS holder, pp.permissions \
         FROM {table} t LEFT JOIN permissioncollections_permissions pp \
         ON pp.permissioncollections_id = t.{table}_id ORDER BY t.entity_id, t.{key_col}"
    );
    let mut out: HashMap<Id, Vec<(Id, Vec<String>)>> = HashMap::new();
    for r in sqlx::query(&sql).fetch_all(&mut *c).await? {
        let entity: Id = r.get("entity_id");
        let holder: Id = r.get("holder");
        let perm: Option<String> = r.get("permissions");
        let list = out.entry(entity).or_default();
        let idx = match list.iter().position(|(h, _)| *h == holder) {
            Some(i) => i,
            None => {
                list.push((holder, vec![]));
                list.len() - 1
            }
        };
        if let Some(p) = perm {
            list[idx].1.push(p);
        }
    }
    Ok(out)
}

//! A consistent, in-memory copy of the slice's rows, read in one transaction.
//!
//! The original works on a Hibernate session: eager associations are loaded
//! with their entities, and permission checks look at the loaded maps. A
//! snapshot gives the same view, and it keeps the filter, projection and
//! permission logic simple.

use std::collections::{BTreeMap, HashMap, HashSet};

use sqlx::{PgConnection, Row};

use crate::err::AppResult;
use crate::jsonx::prop_from_db;
use crate::model::*;

#[derive(Default)]
pub struct Snap {
    pub users: BTreeMap<Id, User>,
    pub groups: BTreeMap<Id, UserGroup>,
    pub roles: BTreeMap<Id, Role>,
    pub layers: BTreeMap<Id, Layer>,
    pub sources: BTreeMap<Id, DataSource>,
    pub appearances: BTreeMap<Id, Appearance>,
    /// (user id, group id) pairs of `user_usergroup`.
    pub memberships: HashSet<(Id, Id)>,
    /// entity id -> (user id, permissions) from `userpermissions`.
    pub user_perms: HashMap<Id, Vec<(Id, Vec<String>)>>,
    /// entity id -> (group id, permissions) from `grouppermissions`.
    pub group_perms: HashMap<Id, Vec<(Id, Vec<String>)>>,
}

impl Snap {
    pub async fn load(c: &mut PgConnection) -> AppResult<Snap> {
        let mut s = Snap::default();

        // ---- roles
        for r in sqlx::query("SELECT id, name, description FROM roles ORDER BY id")
            .fetch_all(&mut *c)
            .await?
        {
            let id: Id = r.get("id");
            s.roles.insert(
                id,
                Role {
                    id: Some(id),
                    name: r.get("name"),
                    description: r.get("description"),
                },
            );
        }

        // ---- users (with role ids and group ids)
        let mut user_roles: HashMap<Id, Vec<Id>> = HashMap::new();
        for r in sqlx::query("SELECT user_id, role_id FROM users_roles ORDER BY user_id, role_id")
            .fetch_all(&mut *c)
            .await?
        {
            user_roles.entry(r.get("user_id")).or_default().push(r.get("role_id"));
        }
        for r in sqlx::query("SELECT user_id, usergroup_id FROM user_usergroup")
            .fetch_all(&mut *c)
            .await?
        {
            let (u, g): (Id, Id) = (r.get("user_id"), r.get("usergroup_id"));
            s.memberships.insert((u, g));
        }
        let mut user_groups: BTreeMap<Id, Vec<Id>> = BTreeMap::new();
        for (u, g) in &s.memberships {
            user_groups.entry(*u).or_default().push(*g);
        }
        for v in user_groups.values_mut() {
            v.sort();
        }
        for r in sqlx::query(
            "SELECT u.id, u.accountname, u.active, u.password, p.firstname, p.lastname, \
             p.email, p.birthday, p.language FROM users u JOIN persons p ON p.id = u.id ORDER BY u.id",
        )
        .fetch_all(&mut *c)
        .await?
        {
            let id: Id = r.get("id");
            let role_ids = user_roles.get(&id).cloned().unwrap_or_default();
            let roles: Vec<Role> = role_ids.iter().filter_map(|rid| s.roles.get(rid).cloned()).collect();
            let groups: Vec<GroupRef> = user_groups
                .get(&id)
                .map(|gs| {
                    gs.iter()
                        .map(|g| GroupRef { id: Some(*g), resolve: false })
                        .collect()
                })
                .unwrap_or_default();
            s.users.insert(
                id,
                User {
                    id: Some(id),
                    first_name: r.get("firstname"),
                    last_name: r.get("lastname"),
                    email: r.get("email"),
                    birthday: r.get("birthday"),
                    language: r.get("language"),
                    account_name: r.get("accountname"),
                    password: r.get("password"),
                    active: r.get::<Option<bool>, _>("active").unwrap_or(false),
                    roles: Some(roles),
                    user_groups: Some(groups),
                },
            );
        }

        // ---- groups (members, roles, owner)
        let mut group_roles: HashMap<Id, Vec<Id>> = HashMap::new();
        for r in sqlx::query("SELECT usergroup_id, role_id FROM usergroups_roles ORDER BY usergroup_id, role_id")
            .fetch_all(&mut *c)
            .await?
        {
            group_roles.entry(r.get("usergroup_id")).or_default().push(r.get("role_id"));
        }
        for r in sqlx::query("SELECT id, name, owner_id FROM usergroups ORDER BY id")
            .fetch_all(&mut *c)
            .await?
        {
            let id: Id = r.get("id");
            let owner_id: Option<Id> = r.get("owner_id");
            let members: Vec<User> = s
                .memberships
                .iter()
                .filter(|(_, g)| *g == id)
                .filter_map(|(u, _)| s.users.get(u).cloned())
                .collect();
            let mut members = members;
            members.sort_by_key(|u| u.id);
            let roles: Vec<Role> = group_roles
                .get(&id)
                .map(|rs| rs.iter().filter_map(|rid| s.roles.get(rid).cloned()).collect())
                .unwrap_or_default();
            s.groups.insert(
                id,
                UserGroup {
                    id: Some(id),
                    name: r.get("name"),
                    owner: owner_id.and_then(|o| s.users.get(&o).cloned()),
                    members: Some(members),
                    roles: Some(roles),
                },
            );
        }

        // ---- extents and tile grids
        let mut extents: HashMap<Id, Extent> = HashMap::new();
        for r in sqlx::query(
            "SELECT id, lowerleft_x, lowerleft_y, upperright_x, upperright_y FROM extents",
        )
        .fetch_all(&mut *c)
        .await?
        {
            let id: Id = r.get("id");
            extents.insert(
                id,
                Extent {
                    id: Some(id),
                    lower_left: point_opt(r.get("lowerleft_x"), r.get("lowerleft_y")),
                    upper_right: point_opt(r.get("upperright_x"), r.get("upperright_y")),
                },
            );
        }
        let mut tg_res: HashMap<Id, Vec<f64>> = HashMap::new();
        for r in sqlx::query(
            "SELECT tilegrid_id, resolution FROM tilegrid_resolution ORDER BY tilegrid_id, idx",
        )
        .fetch_all(&mut *c)
        .await?
        {
            let v: Option<f64> = r.get("resolution");
            tg_res.entry(r.get("tilegrid_id")).or_default().push(v.unwrap_or(0.0));
        }
        let mut wmts_ids: HashSet<Id> = HashSet::new();
        for r in sqlx::query("SELECT id FROM wmtstilegrids").fetch_all(&mut *c).await? {
            wmts_ids.insert(r.get("id"));
        }
        let mut matrix: HashMap<Id, Vec<String>> = HashMap::new();
        for r in sqlx::query("SELECT wmtstilegrids_id, matrixids FROM wmtstilegrids_matrixids ORDER BY wmtstilegrids_id")
            .fetch_all(&mut *c)
            .await?
        {
            let v: Option<String> = r.get("matrixids");
            matrix.entry(r.get("wmtstilegrids_id")).or_default().push(v.unwrap_or_default());
        }
        let mut tilegrids: HashMap<Id, TileGrid> = HashMap::new();
        for r in sqlx::query(
            "SELECT id, type, tilegridorigin_x, tilegridorigin_y, tilesize, tilegridextent_id FROM tilegrids",
        )
        .fetch_all(&mut *c)
        .await?
        {
            let id: Id = r.get("id");
            let wmts = wmts_ids.contains(&id);
            let extent_id: Option<Id> = r.get("tilegridextent_id");
            tilegrids.insert(
                id,
                TileGrid {
                    id: Some(id),
                    type_: r.get("type"),
                    origin: point_opt(r.get("tilegridorigin_x"), r.get("tilegridorigin_y")),
                    extent: extent_id.and_then(|e| extents.get(&e).cloned()),
                    tile_size: r.get("tilesize"),
                    resolutions: Some(tg_res.get(&id).cloned().unwrap_or_default()),
                    wmts,
                    matrix_ids: if wmts {
                        Some(matrix.get(&id).cloned().unwrap_or_default())
                    } else {
                        None
                    },
                },
            );
        }

        // ---- layer appearances
        let mut props: HashMap<Id, Vec<(String, PropValue)>> = HashMap::new();
        for r in sqlx::query("SELECT appearance_id, property, value FROM layerappearances_properties ORDER BY appearance_id, property")
            .fetch_all(&mut *c)
            .await?
        {
            let value: Option<String> = r.get("value");
            props
                .entry(r.get("appearance_id"))
                .or_default()
                .push((r.get("property"), prop_from_db(value.as_deref())));
        }
        for r in sqlx::query(
            "SELECT id, attribution, clickable, hovertemplate, hoverable, maxresolution, \
             minresolution, name, opacity, visible FROM layerappearances ORDER BY id",
        )
        .fetch_all(&mut *c)
        .await?
        {
            let id: Id = r.get("id");
            s.appearances.insert(
                id,
                Appearance {
                    id: Some(id),
                    attribution: r.get("attribution"),
                    hoverable: r.get("hoverable"),
                    clickable: r.get("clickable"),
                    hover_template: r.get("hovertemplate"),
                    properties: Some(props.remove(&id).unwrap_or_default()),
                    name: r.get("name"),
                    max_resolution: r.get("maxresolution"),
                    min_resolution: r.get("minresolution"),
                    opacity: r.get("opacity"),
                    visible: r.get("visible"),
                },
            );
        }

        // ---- data sources
        s.sources = load_sources(c, &tilegrids, &extents).await?;

        // ---- layers
        for r in sqlx::query("SELECT id, name, description, source_id, appearance_id FROM layers ORDER BY id")
            .fetch_all(&mut *c)
            .await?
        {
            let id: Id = r.get("id");
            let source_id: Option<Id> = r.get("source_id");
            let appearance_id: Option<Id> = r.get("appearance_id");
            s.layers.insert(
                id,
                Layer {
                    id: Some(id),
                    name: r.get("name"),
                    description: r.get("description"),
                    source: source_id.and_then(|sid| s.sources.get(&sid).cloned()),
                    appearance: appearance_id.and_then(|aid| s.appearances.get(&aid).cloned()),
                },
            );
        }

        // ---- permissions
        s.user_perms = load_perms(c, "userpermissions", "userpermissions_key").await?;
        s.group_perms = load_perms(c, "grouppermissions", "grouppermissions_key").await?;

        Ok(s)
    }

    /// All entities of a kind, in id order.
    pub fn all(&self, kind: Kind) -> Vec<Ent> {
        match kind {
            Kind::User => self.users.values().cloned().map(Ent::User).collect(),
            Kind::Group => self.groups.values().cloned().map(Ent::Group).collect(),
            Kind::Role => self.roles.values().cloned().map(Ent::Role).collect(),
            Kind::Layer => self.layers.values().cloned().map(Ent::Layer).collect(),
            Kind::Source => self.sources.values().cloned().map(Ent::Source).collect(),
            Kind::Appearance => self.appearances.values().cloned().map(Ent::Appearance).collect(),
        }
    }

    pub fn get(&self, kind: Kind, id: Id) -> Option<Ent> {
        match kind {
            Kind::User => self.users.get(&id).cloned().map(Ent::User),
            Kind::Group => self.groups.get(&id).cloned().map(Ent::Group),
            Kind::Role => self.roles.get(&id).cloned().map(Ent::Role),
            Kind::Layer => self.layers.get(&id).cloned().map(Ent::Layer),
            Kind::Source => self.sources.get(&id).cloned().map(Ent::Source),
            Kind::Appearance => self.appearances.get(&id).cloned().map(Ent::Appearance),
        }
    }
}

fn tg_res_unused() {}

fn point_opt(x: Option<f64>, y: Option<f64>) -> Option<Point> {
    match (x, y) {
        (None, None) => None,
        (x, y) => Some(Point {
            x: x.unwrap_or(0.0),
            y: y.unwrap_or(0.0),
        }),
    }
}

async fn load_sources(
    c: &mut PgConnection,
    tilegrids: &HashMap<Id, TileGrid>,
    extents: &HashMap<Id, Extent>,
    _unused: &(),
) -> AppResult<BTreeMap<Id, DataSource>> {
    let mut base: BTreeMap<Id, DataSource> = BTreeMap::new();
    for r in sqlx::query("SELECT id, name, type, url, format FROM layerdatasources ORDER BY id")
        .fetch_all(&mut *c)
        .await?
    {
        let id: Id = r.get("id");
        base.insert(
            id,
            DataSource {
                id: Some(id),
                name: r.get("name"),
                type_: r.get("type"),
                url: r.get("url"),
                format: r.get("format"),
                kind: SourceKind::Wfs(Wfs::default()), // replaced below
            },
        );
    }

    let mut images: HashMap<Id, ImageWms> = HashMap::new();
    for r in sqlx::query(
        "SELECT id, customrequestpath, height, layernames, layerstyles, requestablebypath, version, width \
         FROM imagewmslayerdatasources",
    )
    .fetch_all(&mut *c)
    .await?
    {
        let id: Id = r.get("id");
        images.insert(
            id,
            ImageWms {
                width: r.get("width"),
                height: r.get("height"),
                version: r.get("version"),
                layer_names: r.get("layernames"),
                layer_styles: r.get("layerstyles"),
                requestable_by_path: r.get("requestablebypath"),
                custom_request_path: r.get("customrequestpath"),
            },
        );
    }
    let mut tile_wms: HashMap<Id, (Option<Id>, Option<bool>)> = HashMap::new();
    for r in sqlx::query("SELECT id, request_with_tiled, tilegrid_id FROM tilewmslayerdatasources")
        .fetch_all(&mut *c)
        .await?
    {
        tile_wms.insert(
            r.get("id"),
            (r.get("tilegrid_id"), r.get("request_with_tiled")),
        );
    }
    let mut wfs: HashMap<Id, Wfs> = HashMap::new();
    for r in sqlx::query("SELECT id, typename, typenames, version FROM wfslayerdatasources")
        .fetch_all(&mut *c)
        .await?
    {
        wfs.insert(
            r.get("id"),
            Wfs {
                version: r.get("version"),
                type_name: r.get("typename"),
                type_names: r.get("typenames"),
            },
        );
    }
    let mut urls: HashMap<Id, Vec<String>> = HashMap::new();
    for r in sqlx::query("SELECT wmtslayerdatasources_id, urls FROM wmtslayerdatasources_urls")
        .fetch_all(&mut *c)
        .await?
    {
        let v: Option<String> = r.get("urls");
        urls.entry(r.get("wmtslayerdatasources_id"))
            .or_default()
            .push(v.unwrap_or_default());
    }
    let mut wmts: HashMap<Id, Wmts> = HashMap::new();
    for r in sqlx::query(
        "SELECT id, capabilitiesurl, matrixset, projection, requestencoding, wmtslayer, wmtsstyle, tilegrid_id \
         FROM wmtslayerdatasources",
    )
    .fetch_all(&mut *c)
    .await?
    {
        let id: Id = r.get("id");
        let tg: Option<Id> = r.get("tilegrid_id");
        wmts.insert(
            id,
            Wmts {
                tile_grid: tg.and_then(|t| tilegrids.get(&t).cloned()),
                urls: Some(urls.remove(&id).unwrap_or_default()),
                wmts_layer: r.get("wmtslayer"),
                wmts_style: r.get("wmtsstyle"),
                projection: r.get("projection"),
                matrix_set: r.get("matrixset"),
                request_encoding: r.get("requestencoding"),
                capabilities_url: r.get("capabilitiesurl"),
            },
        );
    }
    let mut res: HashMap<Id, Vec<f64>> = HashMap::new();
    for r in sqlx::query(
        "SELECT xyzlayerdatasrc_id, resolution FROM xyzlayerdatasrc_resolution ORDER BY xyzlayerdatasrc_id, idx",
    )
    .fetch_all(&mut *c)
    .await?
    {
        let bytes: Option<Vec<u8>> = r.get("resolution");
        res.entry(r.get("xyzlayerdatasrc_id"))
            .or_default()
            .push(crate::javaser::decode_double(bytes.as_deref()));
    }
    let mut xyz: HashMap<Id, Xyz> = HashMap::new();
    for r in sqlx::query("SELECT id, center_x, center_y, tilesize, extent_id FROM xyzlayerdatasources")
        .fetch_all(&mut *c)
        .await?
    {
        let id: Id = r.get("id");
        let ext: Option<Id> = r.get("extent_id");
        xyz.insert(
            id,
            Xyz {
                center: point_opt(r.get("center_x"), r.get("center_y")),
                extent: ext.and_then(|e| extents.get(&e).cloned()),
                resolutions: Some(res.remove(&id).unwrap_or_default()),
                tile_size: r.get("tilesize"),
            },
        );
    }

    let mut out = BTreeMap::new();
    for (id, mut ds) in base {
        let kind = if let Some((tg, rwt)) = tile_wms.get(&id) {
            let image = images.get(&id).cloned().unwrap_or_default();
            Some(SourceKind::TileWms(TileWms {
                image,
                tile_grid: tg.and_then(|t| tilegrids.get(&t).cloned()),
                request_with_tiled: *rwt,
            }))
        } else if let Some(i) = images.get(&id) {
            Some(SourceKind::ImageWms(i.clone()))
        } else if let Some(w) = wfs.get(&id) {
            Some(SourceKind::Wfs(w.clone()))
        } else if let Some(w) = wmts.remove(&id) {
            Some(SourceKind::Wmts(w))
        } else if let Some(x) = xyz.remove(&id) {
            Some(SourceKind::Xyz(x))
        } else {
            None
        };
        if let Some(k) = kind {
            ds.kind = k;
            out.insert(id, ds);
        }
    }
    Ok(out)
}

async fn load_perms(
    c: &mut PgConnection,
    table: &str,
    key_col: &str,
) -> AppResult<HashMap<Id, Vec<(Id, Vec<String>)>>> {
    let sql = format!(
        "SELECT t.entity_id, t.{key_col} AS holder, pp.permissions \
         FROM {table} t LEFT JOIN permissioncollections_permissions pp \
         ON pp.permissioncollections_id = t.{table}_id ORDER BY t.entity_id, t.{key_col}"
    );
    let mut out: HashMap<Id, Vec<(Id, Vec<String>)>> = HashMap::new();
    for r in sqlx::query(&sql).fetch_all(&mut *c).await? {
        let entity: Id = r.get("entity_id");
        let holder: Id = r.get("holder");
        let perm: Option<String> = r.get("permissions");
        let list = out.entry(entity).or_default();
        let idx = match list.iter().position(|(h, _)| *h == holder) {
            Some(i) => i,
            None => {
                list.push((holder, vec![]));
                list.len() - 1
            }
        };
        if let Some(p) = perm {
            list[idx].1.push(p);
        }
    }
    Ok(out)
}

//! A consistent, in-memory copy of the slice's rows, read in one transaction.
//!
//! The original works on a Hibernate session: eager associations are loaded
//! with their entities, and permission checks look at the loaded maps. A
//! snapshot gives the same view, and it keeps the filter, projection and
//! permission logic simple.

use std::collections::{BTreeMap, HashMap, HashSet};

use sqlx::{PgConnection, Row};

use crate::err::AppResult;
use crate::jsonx::prop_from_db;
use crate::model::*;

#[derive(Default)]
pub struct Snap {
    pub users: BTreeMap<Id, User>,
    pub groups: BTreeMap<Id, UserGroup>,
    pub roles: BTreeMap<Id, Role>,
    pub layers: BTreeMap<Id, Layer>,
    pub sources: BTreeMap<Id, DataSource>,
    pub appearances: BTreeMap<Id, Appearance>,
    /// (user id, group id) pairs of `user_usergroup`.
    pub memberships: HashSet<(Id, Id)>,
    /// entity id -> (user id, permissions) from `userpermissions`.
    pub user_perms: HashMap<Id, Vec<(Id, Vec<String>)>>,
    /// entity id -> (group id, permissions) from `grouppermissions`.
    pub group_perms: HashMap<Id, Vec<(Id, Vec<String>)>>,
}

impl Snap {
    pub async fn load(c: &mut PgConnection) -> AppResult<Snap> {
        let mut s = Snap::default();

        // ---- roles
        for r in sqlx::query("SELECT id, name, description FROM roles ORDER BY id")
            .fetch_all(&mut *c)
            .await?
        {
            let id: Id = r.get("id");
            s.roles.insert(
                id,
                Role {
                    id: Some(id),
                    name: r.get("name"),
                    description: r.get("description"),
                },
            );
        }

        // ---- users (with role ids and group ids)
        let mut user_roles: HashMap<Id, Vec<Id>> = HashMap::new();
        for r in sqlx::query("SELECT user_id, role_id FROM users_roles ORDER BY user_id, role_id")
            .fetch_all(&mut *c)
            .await?
        {
            user_roles.entry(r.get("user_id")).or_default().push(r.get("role_id"));
        }
        for r in sqlx::query("SELECT user_id, usergroup_id FROM user_usergroup")
            .fetch_all(&mut *c)
            .await?
        {
            let (u, g): (Id, Id) = (r.get("user_id"), r.get("usergroup_id"));
            s.memberships.insert((u, g));
        }
        let mut user_groups: BTreeMap<Id, Vec<Id>> = BTreeMap::new();
        for (u, g) in &s.memberships {
            user_groups.entry(*u).or_default().push(*g);
        }
        for v in user_groups.values_mut() {
            v.sort();
        }
        for r in sqlx::query(
            "SELECT u.id, u.accountname, u.active, u.password, p.firstname, p.lastname, \
             p.email, p.birthday, p.language FROM users u JOIN persons p ON p.id = u.id ORDER BY u.id",
        )
        .fetch_all(&mut *c)
        .await?
        {
            let id: Id = r.get("id");
            let role_ids = user_roles.get(&id).cloned().unwrap_or_default();
            let roles: Vec<Role> = role_ids.iter().filter_map(|rid| s.roles.get(rid).cloned()).collect();
            let groups: Vec<GroupRef> = user_groups
                .get(&id)
                .map(|gs| {
                    gs.iter()
                        .map(|g| GroupRef { id: Some(*g), resolve: false })
                        .collect()
                })
                .unwrap_or_default();
            s.users.insert(
                id,
                User {
                    id: Some(id),
                    first_name: r.get("firstname"),
                    last_name: r.get("lastname"),
                    email: r.get("email"),
                    birthday: r.get("birthday"),
                    language: r.get("language"),
                    account_name: r.get("accountname"),
                    password: r.get("password"),
                    active: r.get::<Option<bool>, _>("active").unwrap_or(false),
                    roles: Some(roles),
                    user_groups: Some(groups),
                },
            );
        }

        // ---- groups (members, roles, owner)
        let mut group_roles: HashMap<Id, Vec<Id>> = HashMap::new();
        for r in sqlx::query("SELECT usergroup_id, role_id FROM usergroups_roles ORDER BY usergroup_id, role_id")
            .fetch_all(&mut *c)
            .await?
        {
            group_roles.entry(r.get("usergroup_id")).or_default().push(r.get("role_id"));
        }
        for r in sqlx::query("SELECT id, name, owner_id FROM usergroups ORDER BY id")
            .fetch_all(&mut *c)
            .await?
        {
            let id: Id = r.get("id");
            let owner_id: Option<Id> = r.get("owner_id");
            let members: Vec<User> = s
                .memberships
                .iter()
                .filter(|(_, g)| *g == id)
                .filter_map(|(u, _)| s.users.get(u).cloned())
                .collect();
            let mut members = members;
            members.sort_by_key(|u| u.id);
            let roles: Vec<Role> = group_roles
                .get(&id)
                .map(|rs| rs.iter().filter_map(|rid| s.roles.get(rid).cloned()).collect())
                .unwrap_or_default();
            s.groups.insert(
                id,
                UserGroup {
                    id: Some(id),
                    name: r.get("name"),
                    owner: owner_id.and_then(|o| s.users.get(&o).cloned()),
                    members: Some(members),
                    roles: Some(roles),
                },
            );
        }

        // ---- extents and tile grids
        let mut extents: HashMap<Id, Extent> = HashMap::new();
        for r in sqlx::query(
            "SELECT id, lowerleft_x, lowerleft_y, upperright_x, upperright_y FROM extents",
        )
        .fetch_all(&mut *c)
        .await?
        {
            let id: Id = r.get("id");
            extents.insert(
                id,
                Extent {
                    id: Some(id),
                    lower_left: point_opt(r.get("lowerleft_x"), r.get("lowerleft_y")),
                    upper_right: point_opt(r.get("upperright_x"), r.get("upperright_y")),
                },
            );
        }
        let mut tg_res: HashMap<Id, Vec<f64>> = HashMap::new();
        for r in sqlx::query(
            "SELECT tilegrid_id, resolution FROM tilegrid_resolution ORDER BY tilegrid_id, idx",
        )
        .fetch_all(&mut *c)
        .await?
        {
            let v: Option<f64> = r.get("resolution");
            tg_res.entry(r.get("tilegrid_id")).or_default().push(v.unwrap_or(0.0));
        }
        let mut wmts_ids: HashSet<Id> = HashSet::new();
        for r in sqlx::query("SELECT id FROM wmtstilegrids").fetch_all(&mut *c).await? {
            wmts_ids.insert(r.get("id"));
        }
        let mut matrix: HashMap<Id, Vec<String>> = HashMap::new();
        for r in sqlx::query("SELECT wmtstilegrids_id, matrixids FROM wmtstilegrids_matrixids ORDER BY wmtstilegrids_id")
            .fetch_all(&mut *c)
            .await?
        {
            let v: Option<String> = r.get("matrixids");
            matrix.entry(r.get("wmtstilegrids_id")).or_default().push(v.unwrap_or_default());
        }
        let mut tilegrids: HashMap<Id, TileGrid> = HashMap::new();
        for r in sqlx::query(
            "SELECT id, type, tilegridorigin_x, tilegridorigin_y, tilesize, tilegridextent_id FROM tilegrids",
        )
        .fetch_all(&mut *c)
        .await?
        {
            let id: Id = r.get("id");
            let wmts = wmts_ids.contains(&id);
            let extent_id: Option<Id> = r.get("tilegridextent_id");
            tilegrids.insert(
                id,
                TileGrid {
                    id: Some(id),
                    type_: r.get("type"),
                    origin: point_opt(r.get("tilegridorigin_x"), r.get("tilegridorigin_y")),
                    extent: extent_id.and_then(|e| extents.get(&e).cloned()),
                    tile_size: r.get("tilesize"),
                    resolutions: Some(tg_res.get(&id).cloned().unwrap_or_default()),
                    wmts,
                    matrix_ids: if wmts {
                        Some(matrix.get(&id).cloned().unwrap_or_default())
                    } else {
                        None
                    },
                },
            );
        }

        // ---- layer appearances
        let mut props: HashMap<Id, Vec<(String, PropValue)>> = HashMap::new();
        for r in sqlx::query("SELECT appearance_id, property, value FROM layerappearances_properties ORDER BY appearance_id, property")
            .fetch_all(&mut *c)
            .await?
        {
            let value: Option<String> = r.get("value");
            props
                .entry(r.get("appearance_id"))
                .or_default()
                .push((r.get("property"), prop_from_db(value.as_deref())));
        }
        for r in sqlx::query(
            "SELECT id, attribution, clickable, hovertemplate, hoverable, maxresolution, \
             minresolution, name, opacity, visible FROM layerappearances ORDER BY id",
        )
        .fetch_all(&mut *c)
        .await?
        {
            let id: Id = r.get("id");
            s.appearances.insert(
                id,
                Appearance {
                    id: Some(id),
                    attribution: r.get("attribution"),
                    hoverable: r.get("hoverable"),
                    clickable: r.get("clickable"),
                    hover_template: r.get("hovertemplate"),
                    properties: Some(props.remove(&id).unwrap_or_default()),
                    name: r.get("name"),
                    max_resolution: r.get("maxresolution"),
                    min_resolution: r.get("minresolution"),
                    opacity: r.get("opacity"),
                    visible: r.get("visible"),
                },
            );
        }

        // ---- data sources
        s.sources = load_sources(c, &tilegrids, &extents).await?;

        // ---- layers
        for r in sqlx::query("SELECT id, name, description, source_id, appearance_id FROM layers ORDER BY id")
            .fetch_all(&mut *c)
            .await?
        {
            let id: Id = r.get("id");
            let source_id: Option<Id> = r.get("source_id");
            let appearance_id: Option<Id> = r.get("appearance_id");
            s.layers.insert(
                id,
                Layer {
                    id: Some(id),
                    name: r.get("name"),
                    description: r.get("description"),
                    source: source_id.and_then(|sid| s.sources.get(&sid).cloned()),
                    appearance: appearance_id.and_then(|aid| s.appearances.get(&aid).cloned()),
                },
            );
        }

        // ---- permissions
        s.user_perms = load_perms(c, "userpermissions", "userpermissions_key").await?;
        s.group_perms = load_perms(c, "grouppermissions", "grouppermissions_key").await?;

        Ok(s)
    }

    /// All entities of a kind, in id order.
    pub fn all(&self, kind: Kind) -> Vec<Ent> {
        match kind {
            Kind::User => self.users.values().cloned().map(Ent::User).collect(),
            Kind::Group => self.groups.values().cloned().map(Ent::Group).collect(),
            Kind::Role => self.roles.values().cloned().map(Ent::Role).collect(),
            Kind::Layer => self.layers.values().cloned().map(Ent::Layer).collect(),
            Kind::Source => self.sources.values().cloned().map(Ent::Source).collect(),
            Kind::Appearance => self.appearances.values().cloned().map(Ent::Appearance).collect(),
        }
    }

    pub fn get(&self, kind: Kind, id: Id) -> Option<Ent> {
        match kind {
            Kind::User => self.users.get(&id).cloned().map(Ent::User),
            Kind::Group => self.groups.get(&id).cloned().map(Ent::Group),
            Kind::Role => self.roles.get(&id).cloned().map(Ent::Role),
            Kind::Layer => self.layers.get(&id).cloned().map(Ent::Layer),
            Kind::Source => self.sources.get(&id).cloned().map(Ent::Source),
            Kind::Appearance => self.appearances.get(&id).cloned().map(Ent::Appearance),
        }
    }
}

fn point_opt(x: Option<f64>, y: Option<f64>) -> Option<Point> {
    match (x, y) {
        (None, None) => None,
        (x, y) => Some(Point {
            x: x.unwrap_or(0.0),
            y: y.unwrap_or(0.0),
        }),
    }
}

async fn load_sources(
    c: &mut PgConnection,
    tilegrids: &HashMap<Id, TileGrid>,
    extents: &HashMap<Id, Extent>,
    _unused: &(),
) -> AppResult<BTreeMap<Id, DataSource>> {
    let mut base: BTreeMap<Id, DataSource> = BTreeMap::new();
    for r in sqlx::query("SELECT id, name, type, url, format FROM layerdatasources ORDER BY id")
        .fetch_all(&mut *c)
        .await?
    {
        let id: Id = r.get("id");
        base.insert(
            id,
            DataSource {
                id: Some(id),
                name: r.get("name"),
                type_: r.get("type"),
                url: r.get("url"),
                format: r.get("format"),
                kind: SourceKind::Wfs(Wfs::default()), // replaced below
            },
        );
    }

    let mut images: HashMap<Id, ImageWms> = HashMap::new();
    for r in sqlx::query(
        "SELECT id, customrequestpath, height, layernames, layerstyles, requestablebypath, version, width \
         FROM imagewmslayerdatasources",
    )
    .fetch_all(&mut *c)
    .await?
    {
        let id: Id = r.get("id");
        images.insert(
            id,
            ImageWms {
                width: r.get("width"),
                height: r.get("height"),
                version: r.get("version"),
                layer_names: r.get("layernames"),
                layer_styles: r.get("layerstyles"),
                requestable_by_path: r.get("requestablebypath"),
                custom_request_path: r.get("customrequestpath"),
            },
        );
    }
    let mut tile_wms: HashMap<Id, (Option<Id>, Option<bool>)> = HashMap::new();
    for r in sqlx::query("SELECT id, request_with_tiled, tilegrid_id FROM tilewmslayerdatasources")
        .fetch_all(&mut *c)
        .await?
    {
        tile_wms.insert(
            r.get("id"),
            (r.get("tilegrid_id"), r.get("request_with_tiled")),
        );
    }
    let mut wfs: HashMap<Id, Wfs> = HashMap::new();
    for r in sqlx::query("SELECT id, typename, typenames, version FROM wfslayerdatasources")
        .fetch_all(&mut *c)
        .await?
    {
        wfs.insert(
            r.get("id"),
            Wfs {
                version: r.get("version"),
                type_name: r.get("typename"),
                type_names: r.get("typenames"),
            },
        );
    }
    let mut urls: HashMap<Id, Vec<String>> = HashMap::new();
    for r in sqlx::query("SELECT wmtslayerdatasources_id, urls FROM wmtslayerdatasources_urls")
        .fetch_all(&mut *c)
        .await?
    {
        let v: Option<String> = r.get("urls");
        urls.entry(r.get("wmtslayerdatasources_id"))
            .or_default()
            .push(v.unwrap_or_default());
    }
    let mut wmts: HashMap<Id, Wmts> = HashMap::new();
    for r in sqlx::query(
        "SELECT id, capabilitiesurl, matrixset, projection, requestencoding, wmtslayer, wmtsstyle, tilegrid_id \
         FROM wmtslayerdatasources",
    )
    .fetch_all(&mut *c)
    .await?
    {
        let id: Id = r.get("id");
        let tg: Option<Id> = r.get("tilegrid_id");
        wmts.insert(
            id,
            Wmts {
                tile_grid: tg.and_then(|t| tilegrids.get(&t).cloned()),
                urls: Some(urls.remove(&id).unwrap_or_default()),
                wmts_layer: r.get("wmtslayer"),
                wmts_style: r.get("wmtsstyle"),
                projection: r.get("projection"),
                matrix_set: r.get("matrixset"),
                request_encoding: r.get("requestencoding"),
                capabilities_url: r.get("capabilitiesurl"),
            },
        );
    }
    let mut res: HashMap<Id, Vec<f64>> = HashMap::new();
    for r in sqlx::query(
        "SELECT xyzlayerdatasrc_id, resolution FROM xyzlayerdatasrc_resolution ORDER BY xyzlayerdatasrc_id, idx",
    )
    .fetch_all(&mut *c)
    .await?
    {
        let bytes: Option<Vec<u8>> = r.get("resolution");
        res.entry(r.get("xyzlayerdatasrc_id"))
            .or_default()
            .push(crate::javaser::decode_double(bytes.as_deref()));
    }
    let mut xyz: HashMap<Id, Xyz> = HashMap::new();
    for r in sqlx::query("SELECT id, center_x, center_y, tilesize, extent_id FROM xyzlayerdatasources")
        .fetch_all(&mut *c)
        .await?
    {
        let id: Id = r.get("id");
        let ext: Option<Id> = r.get("extent_id");
        xyz.insert(
            id,
            Xyz {
                center: point_opt(r.get("center_x"), r.get("center_y")),
                extent: ext.and_then(|e| extents.get(&e).cloned()),
                resolutions: Some(res.remove(&id).unwrap_or_default()),
                tile_size: r.get("tilesize"),
            },
        );
    }

    let mut out = BTreeMap::new();
    for (id, mut ds) in base {
        let kind = if let Some((tg, rwt)) = tile_wms.get(&id) {
            let image = images.get(&id).cloned().unwrap_or_default();
            Some(SourceKind::TileWms(TileWms {
                image,
                tile_grid: tg.and_then(|t| tilegrids.get(&t).cloned()),
                request_with_tiled: *rwt,
            }))
        } else if let Some(i) = images.get(&id) {
            Some(SourceKind::ImageWms(i.clone()))
        } else if let Some(w) = wfs.get(&id) {
            Some(SourceKind::Wfs(w.clone()))
        } else if let Some(w) = wmts.remove(&id) {
            Some(SourceKind::Wmts(w))
        } else if let Some(x) = xyz.remove(&id) {
            Some(SourceKind::Xyz(x))
        } else {
            None
        };
        if let Some(k) = kind {
            ds.kind = k;
            out.insert(id, ds);
        }
    }
    Ok(out)
}

async fn load_perms(
    c: &mut PgConnection,
    table: &str,
    key_col: &str,
) -> AppResult<HashMap<Id, Vec<(Id, Vec<String>)>>> {
    let sql = format!(
        "SELECT t.entity_id, t.{key_col} AS holder, pp.permissions \
         FROM {table} t LEFT JOIN permissioncollections_permissions pp \
         ON pp.permissioncollections_id = t.{table}_id ORDER BY t.entity_id, t.{key_col}"
    );
    let mut out: HashMap<Id, Vec<(Id, Vec<String>)>> = HashMap::new();
    for r in sqlx::query(&sql).fetch_all(&mut *c).await? {
        let entity: Id = r.get("entity_id");
        let holder: Id = r.get("holder");
        let perm: Option<String> = r.get("permissions");
        let list = out.entry(entity).or_default();
        let idx = match list.iter().position(|(h, _)| *h == holder) {
            Some(i) => i,
            None => {
                list.push((holder, vec![]));
                list.len() - 1
            }
        };
        if let Some(p) = perm {
            list[idx].1.push(p);
        }
    }
    Ok(out)
}

