//! The HTTP entry point: authentication and authorisation for `/rest/**`,
//! then routing and method matching as Spring MVC does it.

use std::sync::Arc;

use axum::body::Bytes;
use axum::extract::State;
use axum::http::{header, HeaderMap, Method, StatusCode, Uri};
use axum::response::{IntoResponse, Response};
use sqlx::PgPool;

use crate::auth;
use crate::handlers::{self, Reply};
use crate::model::{Id, Kind};
use crate::perms::Who;
use crate::query;

pub struct AppState {
    pub pool: PgPool,
}

const ROLE_ADMIN: &str = "ROLE_ADMIN";
const ROLE_USER: &str = "ROLE_USER";

/// The six resources of the slice; every user may call them.
