//! SHOGun REST slice (users, groups, roles, layers, layer data sources and
//! layer appearances) as a standalone service on PostgreSQL.
//!
//! Configuration: `DATABASE_URL` (a PostgreSQL URL) and `PORT` (listen on
//! 0.0.0.0).

mod auth;
mod db;
mod err;
mod handlers;
mod javaser;
mod jsonx;
mod model;
mod perms;
mod query;
mod server;
mod snap;
mod tx;

use std::sync::Arc;
use std::time::{Duration, Instant};

use sqlx::postgres::PgPoolOptions;

#[tokio::main]
async fn main() {
    let url = std::env::var("DATABASE_URL").expect("DATABASE_URL must be set");
    let port: u16 = std::env::var("PORT")
        .ok()
        .and_then(|p| p.trim().parse().ok())
        .expect("PORT must be set to a port number");

    // The database may still be starting; retry for a while.
    let started = Instant::now();
    let pool = loop {
        match PgPoolOptions::new().max_connections(16).connect(&url).await {
            Ok(pool) => break pool,
            Err(e) => {
                if started.elapsed() > Duration::from_secs(45) {
                    panic!("cannot connect to the database: {e}");
                }
                eprintln!("waiting for the database: {e}");
                tokio::time::sleep(Duration::from_secs(2)).await;
            }
        }
    };

    let state = Arc::new(server::AppState { pool });
    let app = axum::Router::new()
        .fallback(server::handle)
        .with_state(state);

    let listener = tokio::net::TcpListener::bind(("0.0.0.0", port))
        .await
        .expect("cannot bind the port");
    eprintln!("listening on 0.0.0.0:{port}");
    axum::serve(listener, app).await.expect("server failed");
}

