#!/usr/bin/env python3
"""Differential test: replay identical scenarios against the Java reference
(8081, db ref) and the Rust port (8082, db port) and compare responses and rows."""
import base64, json, subprocess, sys, urllib.request, urllib.error

REF = ("http://localhost:8081/rest", "ref")
PORT = ("http://localhost:8082/rest", "port")
SEED = "/tmp/ref_seed.dump"

TABLES = [
    "persons", "users", "roles", "usergroups", "user_usergroup", "users_roles",
    "usergroups_roles", "layers", "layerappearances", "layerappearances_properties",
    "layerdatasources", "imagewmslayerdatasources", "tilewmslayerdatasources",
    "wfslayerdatasources", "wmtslayerdatasources", "wmtslayerdatasources_urls",
    "xyzlayerdatasources", "xyzlayerdatasrc_resolution", "extents", "tilegrids",
    "tilegrid_resolution", "wmtstilegrids", "wmtstilegrids_matrixids",
    "userpermissions", "grouppermissions", "permissioncollections",
    "permissioncollections_permissions", "maps_layers", "hibernate_sequences",
]


def sh(cmd):
    r = subprocess.run(cmd, shell=True, capture_output=True, text=True)
    return r.returncode, r.stdout, r.stderr


def reset(db):
    rc, out, err = sh(f"pg_restore -c --if-exists -d {db} {SEED}")
    # pg_restore prints harmless notices on --clean; only real failures matter
    if "error" in err.lower() and "does not exist" not in err.lower():
        print("reset warnings", db, err[:300])


def psql(db, sql):
    rc, out, err = sh(f"psql -q -X -d {db} -At -v ON_ERROR_STOP=1 -c \"{sql}\"")
    if rc != 0:
        raise RuntimeError(f"psql {db}: {err}")
    return out


def psql_file(db, sql):
    open("/tmp/harness/_setup.sql", "w").write(sql)
    rc, out, err = sh(f"psql -q -X -d {db} -v ON_ERROR_STOP=1 -f /tmp/harness/_setup.sql")
    if rc != 0:
        raise RuntimeError(f"setup {db}: {err}")


def dump(db):
    out = {}
    for t in TABLES:
        rc, o, e = sh(
            f"psql -X -d {db} -At -c \"SELECT COALESCE(jsonb_agg(x ORDER BY x::text), '[]'::jsonb)::text FROM "
            f"(SELECT (to_jsonb(t) - 'created' - 'modified') AS x FROM {t} t) s\""
        )
        out[t] = json.loads(o.strip() or "[]")
    return out


def request(base, step, auth):
    method = step.get("method", "GET")
    url = base + step["path"]
    headers = {}
    if auth:
        cred = base64.b64encode(f"{auth[0]}:{auth[1]}".encode()).decode()
        headers["Authorization"] = "Basic " + cred
    if "accept" in step:
        headers["Accept"] = step["accept"]
    data = None
    if "body" in step:
        b = step["body"]
        data = b.encode() if isinstance(b, str) else json.dumps(b).encode()
        headers["Content-Type"] = "application/json"
    req = urllib.request.Request(url, data=data, method=method, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=60) as resp:
            code, body = resp.status, resp.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as e:
        code, body = e.code, e.read().decode("utf-8", "replace")
    parsed = None
    if body.strip():
        try:
            parsed = json.loads(body)
        except Exception:
            parsed = "<non-json>" if code < 500 else None
    return code, parsed


def norm(v):
    if isinstance(v, list):
        items = [norm(x) for x in v]
        return sorted(items, key=lambda x: json.dumps(x, sort_keys=True))
    if isinstance(v, dict):
        return {k: norm(x) for k, x in v.items()}
    if isinstance(v, float) and v.is_integer():
        return int(v)
    return v


def run_scenario(name, setup, steps, auth_map, check_db=True):
    results = {}
    for label, (base, db) in (("ref", REF), ("port", PORT)):
        reset(db)
        if setup:
            psql_file(db, setup)
        log = []
        for step in steps:
            auth = auth_map.get(step.get("as"), None)
            code, body = request(base, step, auth)
            log.append((code, norm(body)))
        results[label] = {"log": log, "db": dump(db) if check_db else None}
    ok = True
    for i, (a, b) in enumerate(zip(results["ref"]["log"], results["port"]["log"])):
        if a != b:
            ok = False
            print(f"  step {i} {steps[i]['method'] if 'method' in steps[i] else 'GET'} {steps[i]['path']}: ref={a[0]} port={b[0]}")
            print("     ref :", json.dumps(a[1], sort_keys=True)[:500])
            print("     port:", json.dumps(b[1], sort_keys=True)[:500])
    if check_db and results["ref"]["db"] != results["port"]["db"]:
        ok = False
        for t in TABLES:
            if results["ref"]["db"][t] != results["port"]["db"][t]:
                print(f"  table {t} differs:")
                print("     ref :", json.dumps(results["ref"]["db"][t], sort_keys=True)[:400])
                print("     port:", json.dumps(results["port"]["db"][t], sort_keys=True)[:400])
    print(("PASS " if ok else "FAIL ") + name)
    return ok

