    if body.strip():
        try:
            parsed = json.loads(body)
        except Exception:
            parsed = "<non-json>" if code < 500 else None
    return code, parsed


def norm(v):
    if isinstance(v, list):
        items = [norm(x) for x in v]
        return sorted(items, key=lambda x: json.dumps(x, sort_keys=True))
    if isinstance(v, dict):
        return {k: norm(x) for k, x in v.items()}
    if isinstance(v, float) and v.is_integer():
        return int(v)
    return v


def run_scenario(name, setup, steps, auth_map, check_db=True):
    results = {}
    for label, (base, db) in (("ref", REF), ("port", PORT)):
        reset(db)
        if setup:
            psql_file(db, setup)
        log = []
        for step in steps:
            auth = auth_map.get(step.get("as"), None)
            code, body = request(base, step, auth)
            log.append((code, norm(body)))
        results[label] = {"log": log, "db": dump(db) if check_db else None}
    ok = True
    for i, (a, b) in enumerate(zip(results["ref"]["log"], results["port"]["log"])):
        if a != b:
            ok = False
            print(f"  step {i} {steps[i]['method'] if 'method' in steps[i] else 'GET'} {steps[i]['path']}: ref={a[0]} port={b[0]}")
            print("     ref :", json.dumps(a[1], sort_keys=True)[:500])
            print("     port:", json.dumps(b[1], sort_keys=True)[:500])
    if check_db and results["ref"]["db"] != results["port"]["db"]:
        ok = False
        for t in TABLES:
            if results["ref"]["db"][t] != results["port"]["db"][t]:
