//! Tests against a PostgreSQL database with `schema.sql` loaded. They run when
//! `DATABASE_URL` is set and skip otherwise. Every row they create is removed
//! again, so the database is left as it was found.

use axum::http::StatusCode;
use sqlx::postgres::PgPoolOptions;
use sqlx::PgPool;

use crate::handlers;
use crate::model::Kind;
use crate::perms::Who;
use crate::query;

const ADMIN: Who = Who { id: 0, admin: true };

async fn pool() -> Option<PgPool> {
    let url = std::env::var("DATABASE_URL").ok()?;
    PgPoolOptions::new().max_connections(4).connect(&url).await.ok()
}

fn id_of(body: &Option<serde_json::Value>) -> i32 {
    body.as_ref().and_then(|b| b["id"].as_i64()).expect("response has an id") as i32
}

#[tokio::test]
async fn role_round_trip() {
    let Some(pool) = pool().await else {
        eprintln!("DATABASE_URL not set: skipping the database tests");
        return;
    };
    let tag = format!("TEST_{}_{}", std::process::id(), chrono::Utc::now().timestamp_millis());

    // POST: created with the next id from the sequence
    let body = format!(r#"{{"name":"{tag}","description":"first"}}"#);
    let created = handlers::create(&pool, Kind::Role, body.as_bytes(), ADMIN)
        .await
        .expect("admin may create");
    assert_eq!(created.status, StatusCode::CREATED);
    let id = id_of(&created.body);

    // GET one
    let got = handlers::get_one(&pool, Kind::Role, id, ADMIN).await.expect("found");
    assert_eq!(got.body.as_ref().unwrap()["name"], tag);

    // PUT: partial update keeps the other fields
    let put = format!(r#"{{"id":{id},"description":"changed"}}"#);
    let updated = handlers::update(&pool, Kind::Role, id, put.as_bytes(), ADMIN)
        .await
        .expect("updated");
    assert_eq!(updated.status, StatusCode::OK);
    let got = handlers::get_one(&pool, Kind::Role, id, ADMIN).await.expect("found");
    let got = got.body.unwrap();
    assert_eq!(got["description"], "changed");
    assert_eq!(got["name"], tag.as_str());

    // GET /filter by name
    let params = query::parse_params(Some(&format!("name={tag}")));
    let found = handlers::filter(&pool, Kind::Role, &params, ADMIN).await.expect("filter");
    assert_eq!(found.body.unwrap().as_array().unwrap().len(), 1);

    // output:only restricts the fields; the projected id is null
    let params = query::parse_params(Some("output:only=name"));
    let listed = handlers::list(&pool, Kind::Role, &params, ADMIN).await.expect("list");
    let mine = listed
        .body
        .unwrap()
        .as_array()
        .unwrap()
        .iter()
        .find(|r| r["name"] == tag.as_str())
        .cloned()
        .expect("our role is listed");
    assert!(mine["id"].is_null());

    // DELETE, then the row is gone
    let deleted = handlers::delete(&pool, Kind::Role, id, ADMIN).await.expect("deleted");
    assert_eq!(deleted.status, StatusCode::NO_CONTENT);
    assert_eq!(
        handlers::get_one(&pool, Kind::Role, id, ADMIN).await.err(),
        Some(StatusCode::NOT_FOUND)
    );
}

#[tokio::test]
async fn non_admin_cannot_create_and_missing_rows_are_404() {
    let Some(pool) = pool().await else {
        eprintln!("DATABASE_URL not set: skipping the database tests");
        return;
    };
    let user = Who { id: 0, admin: false };
    assert_eq!(
        handlers::create(&pool, Kind::Role, br#"{"name":"nope"}"#, user).await.err(),
        Some(StatusCode::BAD_REQUEST)
    );
    assert_eq!(
        handlers::get_one(&pool, Kind::Role, i32::MAX, ADMIN).await.err(),
        Some(StatusCode::NOT_FOUND)
