import json, random, re, sys
sys.path.insert(0, "/tmp/harness")
import compare as C

SEED = int(sys.argv[1]) if len(sys.argv) > 1 else 1
N = int(sys.argv[2]) if len(sys.argv) > 2 else 200
rnd = random.Random(SEED)

src = open("/tmp/harness/scenarios.py").read()
setup = re.search(r'BASE_SETUP = """(.*?)"""', src, re.S).group(1)
AUTH = {"admin": ("admin", "shogun"), "user": ("user", "shogun"), "noroles": ("noroles", "shogun")}

RES = {
    "users": "/rest/users", "groups": "/rest/groups", "roles": "/rest/roles",
    "layers": "/rest/layers", "layerdatasources": "/rest/layerdatasources",
    "layerappearances": "/rest/layerappearances",
}
IDS = {"users": [3, 4], "groups": [5, 6], "roles": [1, 2], "layers": [15, 16, 950],
       "layerdatasources": [12, 13, 900, 910, 920, 930], "layerappearances": [14, 940]}
STRINGS = ["x", "", "ROLE_NEW", "a b", "12", "true", "1.5", "null", "é", "OSM-WMS", "desc", "user", "admin"]


def rand_scalar(kind):
    r = rnd.random()
    if r < 0.12:
        return None
    if kind == "str":
        return rnd.choice(STRINGS) if r < 0.9 else rnd.randint(-5, 999)
    if kind == "int":
        return rnd.choice([rnd.randint(-3, 9), "3", "abc", "", 2.0, True, 1.9]) if r < 0.9 else rnd.randint(0, 10**9)
    if kind == "bool":
        return rnd.choice([True, False, "true", "no", 1, 0, "x"])
    if kind == "dbl":
        return rnd.choice([rnd.random() * 100, 0.5, 2, "1.5", "abc", 1e7, -3])
    if kind == "date":
        return rnd.choice(["1990-01-02", "2001-13-01", [1990, 1, 2], "", "x"])
    if kind == "locale":
        return rnd.choice(["de_DE", "en", "EN_us", "", "fr_FR_x"])
    raise ValueError(kind)


def ref_obj(res):
    ids = IDS.get(res, [])
    if rnd.random() < 0.1:
        return {"id": rnd.randint(990, 999)}
    if not ids:
        return {"id": 1}
    return {"id": rnd.choice(ids)}


def body_for(res, mode):
    fields = {
        "users": {"firstName": "str", "lastName": "str", "email": "str", "birthday": "date",
                  "language": "locale", "accountName": "str", "password": "str", "active": "bool"},
        "groups": {"name": "str"},
        "roles": {"name": "str", "description": "str"},
        "layers": {"name": "str", "description": "str"},
        "layerdatasources": {"name": "str", "type": "str", "url": "str", "format": "str", "width": "int",
                             "height": "int", "version": "str", "layerNames": "str", "requestableByPath": "bool",
                             "typeName": "str", "typeNames": "str", "wmtsLayer": "str", "tileSize": "int",
                             "requestWithTiled": "bool"},
        "layerappearances": {"attribution": "str", "hoverable": "bool", "clickable": "bool",
                             "hoverTemplate": "str", "name": "str", "maxResolution": "dbl",
                             "minResolution": "dbl", "opacity": "dbl", "visible": "bool"},
    }[res]
    body = {}
    for f, kind in fields.items():
        if rnd.random() < (0.5 if mode == "put" else 0.35):
            body[f] = rand_scalar(kind)
    if res == "users":
        if rnd.random() < 0.3:
            body["roles"] = [ref_obj("roles") for _ in range(rnd.randint(0, 2))]
        if rnd.random() < 0.3:
            body["userGroups"] = [rnd.choice([rnd.choice([5, 6]), ref_obj("groups")]) for _ in range(rnd.randint(0, 2))]
    if res == "groups":
        if rnd.random() < 0.3:
            body["owner"] = ref_obj("users") if rnd.random() < 0.8 else None
        if rnd.random() < 0.3:
            body["members"] = [ref_obj("users") for _ in range(rnd.randint(0, 3))]
        if rnd.random() < 0.3:
            body["roles"] = [ref_obj("roles") for _ in range(rnd.randint(0, 2))]
    if res == "layers":
        if rnd.random() < 0.3:
            ap = {"attribution": rnd.choice(["a", None]), "opacity": rand_scalar("dbl")}
            if rnd.random() < 0.5:
                ap["properties"] = {rnd.choice(["k", "n", "b"]): rnd.choice([1, "two", True, None, 1.5, "true"])}
            if rnd.random() < 0.3:
                ap["id"] = rnd.choice([14, 940, 999])
            body["appearance"] = ap if rnd.random() < 0.9 else None
        if rnd.random() < 0.05:
            body["source"] = {"id": 12}
    if res == "layerappearances" and rnd.random() < 0.4:
        body["properties"] = rnd.choice([None, {}, {"a": 1, "b": "2", "c": None}, {"d": [1, 2]}])
    if res == "layerdatasources":
        if rnd.random() < 0.3:
            body["tileGrid"] = rnd.choice([None, {"id": 11}, {"tileSize": 128, "tileGridResolutions": [1.0, 2.0]}])
        if rnd.random() < 0.2:
            body["center"] = rnd.choice([None, {"x": 1, "y": 2}])
        if rnd.random() < 0.2:
            body["resolutions"] = rnd.choice([None, [], [None], [1]])
        if rnd.random() < 0.2:
            body["extent"] = rnd.choice([None, {"id": 911}, {"lowerLeft": {"x": 1, "y": 1}}])
        if rnd.random() < 0.2:
            body["urls"] = rnd.choice([None, [], ["u1", "u9"]])
    if rnd.random() < 0.05:
        body[rnd.choice(["bogus", "created", "password2", "modified"])] = 1
    return body


def random_op():
    res = rnd.choice(list(RES))
    base = RES[res]
    who = rnd.choice(["admin", "admin", "admin", "user", "noroles"])
    r = rnd.random()
    if r < 0.25:
        b = body_for(res, "post")
        if rnd.random() < 0.1 and res == "users":
            b["id"] = rnd.choice([None, 5])
        return {"as": who, "method": "POST", "path": base, "body": b, "res": res}
    if r < 0.6:
        i = rnd.choice(IDS[res] + [rnd.randint(900, 999)])
        b = body_for(res, "put")
        b["id"] = i if rnd.random() < 0.95 else i + 1
        return {"as": who, "method": "PUT", "path": f"{base}/{i}", "body": b, "res": res}
    if r < 0.7:
        i = rnd.choice(IDS[res] + [rnd.randint(40, 60)])
        return {"as": who, "method": "DELETE", "path": f"{base}/{i}", "res": res}
    if r < 0.85:
        q = rnd.choice(["", "?output:only=name", "?output:only=id,name", "?output:only=accountName",
                        "?name=x", "?accountName=admin", "?active=true", "?id=3", "?type=TileWMS",
                        "?output:only=bogus", "?opacity=0.5"])
        return {"as": who, "method": "GET", "path": base + q, "res": res}
    i = rnd.choice(IDS[res])
    sub = {"users": "/userGroups", "groups": "/users"}.get(res, "")
    return {"as": who, "method": "GET", "path": f"{base}/{i}{sub}", "res": res}


def main():
    C.reset("ref"); C.psql_file("ref", setup)
    C.reset("port"); C.psql_file("port", setup)
    auth = AUTH
    for n in range(N):
        op = random_op()
        if op["method"] == "POST" and op["res"] == "layerdatasources":
            pass
        results = {}
        for label, (base, db) in (("ref", C.REF), ("port", C.PORT)):
            code, body = C.request(base, {"method": op["method"], "path": op["path"], "body": op.get("body")} if "body" in op else {"method": op["method"], "path": op["path"]}, auth.get(op["as"]))
            results[label] = (code, C.norm(body))
        if results["ref"] != results["port"]:
            print(f"DIVERGENCE at op {n}: {op['method']} {op['path']} as {op['as']}")
            print("  body:", json.dumps(op.get("body"))[:300])
            print("  ref :", results["ref"][0], json.dumps(results["ref"][1])[:400])
            print("  port:", results["port"][0], json.dumps(results["port"][1])[:400])
            return 1
        if n % 8 == 7:
            dr, dp = C.dump("ref"), C.dump("port")
            if dr != dp:
                for t in C.TABLES:
                    if dr[t] != dp[t]:
                        print(f"DB DIVERGENCE after op {n} ({op['method']} {op['path']}) in {t}")
                        print("  ref :", json.dumps(dr[t], sort_keys=True)[:500])
                        print("  port:", json.dumps(dp[t], sort_keys=True)[:500])
                        return 1
    print(f"seed {SEED}: {N} operations identical")
    return 0


if __name__ == "__main__":
    sys.exit(main())

